# ── Backtest ──────────────────────────────────────────────────────
_backtest_jobs: Dict[str, dict] = {}
_backtest_active_by_user: Dict[int, str] = {}


async def _run_backtest_job(job_id: str, payload: StrategyPayload, request: Request) -> None:
    """Run the existing exact backtest outside the browser request lifetime.

    The Request is only still here because api_run_backtest reads the owner off
    request.state to save the run. Nothing else about it may be touched: by the
    time this runs the response has been sent and the connection may be gone.
    """
    job = _backtest_jobs.get(job_id)
    if job is None:
        return
    job["status"] = "running"
    job["started_at"] = datetime.now().isoformat(timespec="seconds")
    job["stage"] = "Preparing the replay…"

    def _report(text: str) -> None:
        job["stage"] = text

    _backtest_stage.set(_report)
    try:
        job["result"] = await api_run_backtest(payload, request)
        job["status"] = "complete"
    except Exception as exc:
        _logger.exception("[BACKTEST] Background job %s crashed", job_id)
        job["status"] = "error"
        job["message"] = f"Backtest failed: {exc}"
    finally:
        job["finished_at"] = datetime.now().isoformat(timespec="seconds")
        owner_id = int(job["user_id"])
        if _backtest_active_by_user.get(owner_id) == job_id:
            _backtest_active_by_user.pop(owner_id, None)


@app.post("/api/backtest/jobs")
async def start_backtest_job(payload: StrategyPayload, request: Request):
    """Queue a long historical replay and return before any gateway timeout."""
    user_id = _request_user_id(request)
    active_id = _backtest_active_by_user.get(user_id)
    active_job = _backtest_jobs.get(active_id or "")
    if active_job and active_job.get("status") in {"queued", "running"}:
        # 409 carries the running job's id so the page can ATTACH to it. Only
        # one replay may run per account, but the answer to "you already have
        # one" is to show it, not to leave the user with no way to reach it.
        return JSONResponse(
            status_code=409,
            content={
                "status": active_job.get("status"),
                "message": "A backtest is already running for this account — showing that one.",
                "job_id": active_id,
                "attach": True,
            },
        )

    job_id = secrets.token_urlsafe(18)
    _backtest_jobs[job_id] = {
        "user_id": user_id,
        "status": "queued",
        "created_at": datetime.now().isoformat(timespec="seconds"),
        # Kept so a page ATTACHING to this job renders it against the strategy
        # it actually ran. Without it, changing the strategy and pressing Run
        # while an older replay was still going would draw that replay's
        # numbers under the new strategy's name.
        "payload": payload.model_dump(),
    }
    _backtest_active_by_user[user_id] = job_id
    asyncio.create_task(_run_backtest_job(job_id, payload, request))
    return {"status": "queued", "job_id": job_id}


@app.get("/api/backtest/jobs/{job_id}")
async def get_backtest_job(job_id: str, request: Request):
    """Return progress or the completed result, scoped to the owner."""
    job = _backtest_jobs.get(job_id)
    if not job or int(job.get("user_id") or 0) != _request_user_id(request):
        raise HTTPException(status_code=404, detail="Backtest job not found")
    response = {key: value for key, value in job.items() if key not in {"user_id", "result"}}
    if job.get("status") == "complete":
        response["result"] = job.get("result")
    return response


@app.get("/api/backtest/jobs")
async def list_backtest_job(request: Request):
    """The caller's in-flight replay, if there is one.

    This is what lets a reloaded Results page pick a running backtest back up
    instead of showing an empty screen while the work carries on unseen.
    """
    user_id = _request_user_id(request)
    job_id = _backtest_active_by_user.get(user_id)
    job = _backtest_jobs.get(job_id or "")
    if not job or job.get("status") not in {"queued", "running"}:
        return {"status": "idle"}
    return {"status": job.get("status"), "job_id": job_id, "payload": job.get("payload")}


@app.post("/api/backtest")
async def api_run_backtest(payload: StrategyPayload, request: Request):
    try:
        from_date = payload.from_date or config.DEFAULT_FROM
        to_date = payload.to_date or config.DEFAULT_TO
        entry_conditions = payload.entry_conditions or DEFAULT_ENTRY_CONDITIONS
        exit_conditions = payload.exit_conditions or DEFAULT_EXIT_CONDITIONS
        contract = validate_strategy_contract(payload.indicators, entry_conditions, exit_conditions)
        normalized_indicators = contract["normalized_indicators"]
        if contract["errors"]:
            return {
                "status": "error",
                "message": "Strategy validation failed:\n- " + "\n- ".join(contract["errors"]),
                "validation": contract,
            }

        execution_timeframe = infer_execution_timeframe(normalized_indicators, entry_conditions, default=5)
        try:
            tf_spec = resolve_strategy_timeframe(
                normalized_indicators,
                default=execution_timeframe,
                execution_hint=execution_timeframe,
            )
        except ValueError as tf_err:
            return {"status": "error", "message": str(tf_err)}
        candle_interval = str(tf_spec.fetch)

        _logger.info(
            "[BACKTEST] Validated request timeframe=%s indicator_count=%s entry_condition_count=%s "
            "exit_condition_count=%s leg_count=%s",
            describe_timeframe(tf_spec),
            len(normalized_indicators),
            len(entry_conditions),
            len(exit_conditions),
            len(payload.legs or []),
        )

        # 1. Fetch data with segment-aware routing + fallback
        print(f"[BACKTEST] Fetching data from {from_date} to {to_date}...")
        try:
            df_raw = await asyncio.to_thread(
                _fetch_data,
                instrument=payload.instrument,
                from_date=from_date,
                to_date=to_date,
                segment=payload.segment,
                candle_interval=candle_interval,
            )
        except Exception as fetch_err:
            error_msg = f"Data fetch failed: {str(fetch_err)}"
            print(f"[BACKTEST] {error_msg}")
            return {"status": "error", "message": error_msg}

        if df_raw is None or df_raw.empty:
            error_msg = "No data returned. Check credentials and date range."
            print(f"[BACKTEST] {error_msg}")
            return {"status": "error", "message": error_msg}

        print(f"[BACKTEST] Data: {len(df_raw)} candles, {df_raw.index[0]} → {df_raw.index[-1]}")

        # Warn if actual data range is shorter than requested, or if using daily candles
        data_range_warning = None
        timeframe_warning = derived_timeframe_warning(tf_spec)
        from datetime import datetime as _dtw

        _from_dt = _dtw.strptime(from_date, "%Y-%m-%d")
        _to_dt = _dtw.strptime(to_date, "%Y-%m-%d")
        _day_span = (_to_dt - _from_dt).days
        if _day_span > INTRADAY_MAX_DAYS:
            data_range_warning = (
                f"📊 Date range is {_day_span} days — automatically using DAILY candles "
                f"for full {from_date} → {to_date} coverage. "
                f"(Dhan intraday history is limited to about 5 years. Daily candles go back further.)"
            )
            print(f"[BACKTEST] {data_range_warning}")
        else:
            actual_start = (
                str(df_raw.index[0].date()) if hasattr(df_raw.index[0], "date") else str(df_raw.index[0])[:10]
            )
            if actual_start > from_date:
                data_range_warning = (
                    f"⚠️ Data starts from {actual_start} (requested {from_date}). "
                    f"Some data may not be available for the requested period."
                )
                print(f"[BACKTEST] {data_range_warning}")

        # 2. Build strategy_config
        strategy_config = payload.model_dump()
        strategy_config["indicators"] = normalized_indicators
        strategy_config["timeframe_minutes"] = tf_spec.requested
        strategy_config["fetch_timeframe_minutes"] = tf_spec.fetch
        if payload.execution_mode == "next_minute":
            # QuantMan's "Next Minute Start": evaluate entries only when the
            # strategy candle closes, execute on the next 1-minute open, and
            # execute signal exits on the following 1-minute open as well.
            strategy_config["execution_timeframe_minutes"] = 1
            strategy_config["entry_evaluation_timeframe_minutes"] = execution_timeframe
            strategy_config["signal_exit_next_open"] = True
        requested_days = max(1, (_to_dt - _from_dt).days + 1)
        premium_target_legs = [
            leg
            for leg in (payload.legs or [])
            if str((leg or {}).get("strike_type") or "").lower() in {"premium_near", "premium_above", "premium_below"}
        ]
        if premium_target_legs:
            try:
                from data.backtest_upstox import UpstoxHistoricalPremiumSelector

                strategy_config["_upstox_premium_selector"] = UpstoxHistoricalPremiumSelector(
                    payload.instrument,
                    progress=_say_stage,
                )
            except Exception as exc:
                return {
                    "status": "error",
                    "message": f"Upstox historical premium data unavailable for this backtest: {exc}",
                }
        strategy_config["allow_synthetic_option_fallback"] = (
            requested_days >= _OPTION_REAL_DATA_MAX_DAYS and not premium_target_legs
        )
        # Runs off the event loop: this fetch is synchronous, network-bound and
        # throttles itself with time.sleep between Dhan chunks. Left inline it
        # stalls every live/paper engine task and the /ws stream for its whole
        # duration, since they all share this loop and the app runs one worker.
        option_pricing = await asyncio.to_thread(
            _fetch_backtest_option_histories, strategy_config, tf_spec, from_date, to_date
        )
        premium_selector = strategy_config.get("_upstox_premium_selector")
        if premium_selector is not None and getattr(premium_selector, "expiries", None):
            first_expiry = premium_selector.expiries[0]
            last_expiry = premium_selector.expiries[-1]
            if _from_dt.date() < first_expiry or _to_dt.date() > last_expiry:
                option_pricing["warnings"].append(
                    "Upstox expired-option coverage currently spans expiries "
                    f"{first_expiry.isoformat()} to {last_expiry.isoformat()}. "
                    "Signals outside that provider window are reported as gaps and are never synthetically priced."
                )
        if option_pricing["errors"]:
            error_msg = "Historical option data unavailable for this backtest:\n- " + "\n- ".join(
                option_pricing["errors"]
            )
            print(f"[BACKTEST] ❌ {error_msg}")
            return {
                "status": "error",
                "message": error_msg,
                "option_pricing": option_pricing,
            }
        if option_pricing["historical_legs"] > 0:
            print(
                f"[BACKTEST] Option pricing: stored/historical candles for {option_pricing['historical_legs']} leg(s)"
            )
        elif any((leg or {}).get("option_type") in ("CE", "PE") for leg in (payload.legs or [])):
            if strategy_config["allow_synthetic_option_fallback"]:
                print(
                    f"[BACKTEST] ⚠️  Option pricing: synthetic-only by range rule "
                    f"({requested_days} days >= {_OPTION_REAL_DATA_MAX_DAYS})"
                )
            else:
                print("[BACKTEST] ⚠️  Option pricing: no usable historical option data")
        for warning in option_pricing["warnings"]:
            print(f"[BACKTEST] ⚠️  {warning}")

        # 3. Run backtest
        print("[BACKTEST] Running backtest engine...")
        try:
            results = await asyncio.to_thread(
                run_backtest,
                df_raw=df_raw,
                entry_conditions=entry_conditions,
                exit_conditions=exit_conditions,
                strategy_config=strategy_config,
            )
        except Exception as bt_err:
            error_msg = f"Backtest execution failed: {str(bt_err)}"
            print(f"[BACKTEST] {error_msg}")
            import traceback

            traceback.print_exc()
            return {"status": "error", "message": error_msg}

        option_data_gaps = strategy_config.get("_option_data_gaps", []) or []
        if option_data_gaps:
            option_pricing["warnings"].append(
                f"Upstox omitted {len(option_data_gaps)} premium-target signal(s) with incomplete historical option data."
            )
            results["option_data_gaps"] = option_data_gaps
        if premium_selector is not None and hasattr(premium_selector, "cache_summary"):
            selection_cache = premium_selector.cache_summary()
            option_pricing["upstox_selection_cache"] = selection_cache
            option_pricing["warnings"].append(
                "Upstox premium-selection cache: "
                f"{selection_cache['selection_hits']} reused, {selection_cache['selection_misses']} newly resolved; "
                f"{selection_cache['candle_requests']} Upstox request(s)."
            )

        print(f"[BACKTEST] Result: {results.get('status')}, Trades: {results.get('stats', {}).get('total_trades', 0)}")

        # Save the run
        if results.get("status") == "success":
            run_entry = {
                "mode": "backtest",
                "run_name": payload.run_name,
                "folder": payload.folder,
                "segment": payload.segment,
                "instrument": payload.instrument,
                "from_date": from_date,
                "to_date": to_date,
                "lots": payload.lots,
                "lot_size": payload.lot_size,
                "stoploss_pct": payload.stoploss_pct,
                "stoploss_rupees": getattr(payload, "stoploss_rupees", 0),
                "sl_type": getattr(payload, "sl_type", "pct"),
                "target_profit_pct": getattr(payload, "target_profit_pct", 0),
                "target_profit_rupees": getattr(payload, "target_profit_rupees", 0),
                "tp_type": getattr(payload, "tp_type", "pct"),
                "indicators": normalized_indicators,
                "entry_conditions": entry_conditions,
                "exit_conditions": exit_conditions,
                "legs": payload.legs,
                "market_open": getattr(payload, "market_open", "09:15") or "09:15",
                "market_close": getattr(payload, "market_close", "15:25") or "15:25",
                "signal_cutoff_time": str(getattr(payload, "signal_cutoff_time", "") or "").strip(),
                "max_trades_per_day": getattr(payload, "max_trades_per_day", 1),
                "max_daily_loss": getattr(payload, "max_daily_loss", 0),
                "initial_capital": getattr(payload, "initial_capital", config.DEFAULT_CAPITAL),
                "combined_sl_rupees": getattr(payload, "combined_sl_rupees", 0),
                "combined_target_rupees": getattr(payload, "combined_target_rupees", 0),
                "combined_sqoff_time": getattr(payload, "combined_sqoff_time", "15:20") or "15:20",
                "fee_pct": getattr(payload, "fee_pct", 0.0),
                "trailing_sl_pct": getattr(payload, "trailing_sl_pct", 0.0),
                "execution_mode": payload.execution_mode,
                "execution_timeframe_minutes": strategy_config.get("execution_timeframe_minutes"),
                "entry_evaluation_timeframe_minutes": strategy_config.get("entry_evaluation_timeframe_minutes"),
                "signal_exit_next_open": strategy_config.get("signal_exit_next_open", False),
                "execution_profile": getattr(payload, "execution_profile", "auto"),
                "spread_bps": getattr(payload, "spread_bps", 0.0),
                "entry_slippage_bps": getattr(payload, "entry_slippage_bps", 0.0),
                "exit_slippage_bps": getattr(payload, "exit_slippage_bps", 0.0),
                "entry_delay_candles": getattr(payload, "entry_delay_candles", 0),
                "signal_exit_delay_candles": getattr(payload, "signal_exit_delay_candles", 0),
                "enforce_capital": getattr(payload, "enforce_capital", False),
                "capital_buffer_pct": getattr(payload, "capital_buffer_pct", 0.0),
                "sell_option_margin_per_lot": getattr(payload, "sell_option_margin_per_lot", 0.0),
                "deploy_config": getattr(payload, "deploy_config", None),
                "option_pricing": {
                    "historical_legs": option_pricing["historical_legs"],
                    "synthetic_legs": option_pricing["synthetic_legs"],
                    "upstox_selection_cache": option_pricing.get("upstox_selection_cache"),
                },
                "option_pricing_warnings": option_pricing["warnings"],
                "stats": results["stats"],
                "monthly": results.get("monthly", []),
                "day_of_week": results.get("day_of_week", []),
                "yearly": results.get("yearly", []),
                "trade_count": results["stats"]["total_trades"],
                "total_pnl": results["stats"]["total_pnl"],
                "created_at": str(datetime.now()),
            }
            # Store all trades (no need to trim)
            all_trades = results.get("trades", [])
            run_entry["trades"] = all_trades
            run_entry["equity"] = results.get("equity", [])
            saved_run = await _db_mod.create_run_record(_request_user_id(request), run_entry)
            results["run_id"] = saved_run["id"]
            print(f"[BACKTEST] Saved as Run #{saved_run['id']}")

        if data_range_warning:
            results["data_range_warning"] = data_range_warning
        if timeframe_warning:
            results["timeframe_warning"] = timeframe_warning
        if option_pricing["warnings"]:
            results["option_pricing_warnings"] = option_pricing["warnings"]
        results["option_pricing"] = {
            "historical_legs": option_pricing["historical_legs"],
            "synthetic_legs": option_pricing["synthetic_legs"],
            "upstox_selection_cache": option_pricing.get("upstox_selection_cache"),
        }
        results["timeframe_info"] = {
            "requested_minutes": tf_spec.requested,
            "fetch_minutes": tf_spec.fetch,
            "derived": tf_spec.derived,
            "all_frames": list(tf_spec.all_frames),
        }

        return results

    except Exception as e:
        import traceback

        error_msg = f"Backtest failed: {str(e)}"
        print(f"[BACKTEST] FATAL ERROR: {error_msg}")
        traceback.print_exc()
        return {"status": "error", "message": error_msg, "details": str(e)}


# ── Live Engine ───────────────────────────────────────────────────
@app.post("/api/live/start")
async def live_start(req: LiveStartRequest, request: Request):
    """Start live auto-trading with full strategy configuration."""
    user_id = _request_user_id(request)
    user = getattr(request.state, "current_user", None) or await _auth_mod.get_current_user(request)
    broker_client, broker_source = _resolve_user_broker_client(user, allow_admin_fallback=True)
    if not broker_client:
        return {"status": "error", "message": _broker_not_configured_message(user, broker_source)}
    live_bucket = _registry_bucket(live_engines, user_id)
    live_task_bucket = _registry_bucket(_live_tasks, user_id)
    stopped_engines = _load_stopped_engines(user_id)
    # Build strategy dict from the request
    strategy_dict = {}
    if req.strategy_config:
        strategy_dict = dict(req.strategy_config)
    else:
        strategy_dict = {
            "strategy_id": int(req.strategy_id or 0),
            "run_name": req.run_name or "Live Strategy",
            "instrument": req.instrument or "26000",
            "indicators": req.indicators or [],
            "max_trades_per_day": int(req.max_trades_per_day or 1),
            "market_open": req.market_open or "09:15",
            "market_close": req.market_close or "15:25",
            "legs": req.legs or [],
            "deploy_config": req.deploy_config or {},
            "max_daily_loss": float(req.max_daily_loss or 0),
            "skip_days_after_profit": int(req.skip_days_after_profit or 0),
            "skip_profit_threshold_rupees": float(req.skip_profit_threshold_rupees or 20000),
            "signal_cutoff_time": str(req.signal_cutoff_time or "").strip(),
            "lots": req.lots,
            "stoploss_pct": req.stoploss_pct,
            "stoploss_rupees": req.stoploss_rupees,
            "sl_type": req.sl_type,
            "target_profit_pct": req.target_profit_pct,
            "target_profit_rupees": req.target_profit_rupees,
            "tp_type": req.tp_type,
            "initial_capital": req.initial_capital,
            "execution_profile": req.execution_profile,
            "enforce_capital": req.enforce_capital,
            "capital_buffer_pct": req.capital_buffer_pct,
            "sell_option_margin_per_lot": req.sell_option_margin_per_lot,
            "poll_interval": 10,
        }
    entry_conditions, exit_conditions = (
        req.entry_conditions or DEFAULT_ENTRY_CONDITIONS,
        req.exit_conditions or DEFAULT_EXIT_CONDITIONS,
    )
    contract = validate_strategy_contract(
        strategy_dict.get("indicators", req.indicators), entry_conditions, exit_conditions
    )
    if contract["errors"]:
        return {
            "status": "error",
            "message": "Strategy validation failed:\n- " + "\n- ".join(contract["errors"]),
            "validation": contract,
        }
    strategy_dict["indicators"] = contract["normalized_indicators"]
    execution_timeframe = infer_execution_timeframe(strategy_dict["indicators"], entry_conditions, default=5)
    try:
        tf_spec = resolve_strategy_timeframe(
            strategy_dict["indicators"],
            default=execution_timeframe,
            execution_hint=execution_timeframe,
        )
    except ValueError as tf_err:
        return {"status": "error", "message": str(tf_err)}
    strategy_dict["strategy_id"] = int(strategy_dict.get("strategy_id") or req.strategy_id or 0)
    strategy_dict["timeframe_minutes"] = tf_spec.requested
    strategy_dict["_user_id"] = user_id
    strategy_dict["fetch_timeframe_minutes"] = tf_spec.fetch

    await _sync_saved_strategy_from_runtime(
        user_id,
        strategy_dict.get("strategy_id", 0),
        dict(req.strategy_config or strategy_dict),
        entry_conditions,
        exit_conditions,
        source_label="live start",
    )

    deploy_config = req.deploy_config or strategy_dict.get("deploy_config", {})

    # Generate run_id from strategy name
    run_id = strategy_dict.get("run_name", "live") or "live"

    # Clear only the stopped snapshot for this exact engine identity
    stopped_engines.pop(_engine_snapshot_key(run_id, "auto"), None)
    _save_stopped_engines(user_id)

    # If an engine with same run_id exists, save its results before replacing
    old_engine = live_bucket.get(run_id)
    if old_engine:
        if old_engine.running and getattr(old_engine, "positions", None):
            return {
                "status": "error",
                "message": "An active live engine with open broker positions already exists for this run. Stop it and wait for square-off before redeploying.",
            }
        try:
            old_status = old_engine.get_status()
            if old_engine.running:
                old_engine.stop()
                task = live_task_bucket.pop(run_id, None)
                if task and not task.done():
                    task.cancel()
            await _save_live_run_to_history(old_status, explicit_user_id=getattr(old_engine, "_user_id", None))
        except Exception as e:
            print(f"[LIVE] Failed to save old engine {run_id}: {e}")
        live_bucket.pop(run_id, None)

    # Create a new engine instance for this strategy
    engine = LiveEngine(broker_client, run_id=run_id, state_dir=_engine_state_dir(user_id))
    engine.configure(
        strategy=strategy_dict,
        entry_conditions=entry_conditions,
        exit_conditions=exit_conditions,
        deploy_config=deploy_config,
    )
    engine._user_id = user_id

    # Inject WebSocket feed if available — starts WS + subscribes index
    if _market_feed and HAS_DHAN_FEED:
        instrument = strategy_dict.get("instrument", "26000")
        _market_feed.subscribe_index(instrument)
        if not _market_feed.is_running:
            _market_feed.start()
        engine.set_feed(_market_feed)

    # Set running IMMEDIATELY so UI never sees a stale "stopped" state
    engine.running = True
    engine.event_log = []
    engine.positions = []
    # Preserve historical closed trades so "Completed Trades" panel shows past results
    engine.closed_trades = engine._load_trade_history() if hasattr(engine, "_load_trade_history") else []
    engine.in_trade = False
    engine.trades_today = 0

    await _reset_alert_state_for_start(user_id, run_id, engine.closed_trades)

    async def broadcast(event: dict):
        await _broadcast_user_ws_json(user_id, {"source": "live", "run_id": run_id, **event})
        await _check_trade_alerts(run_id, "Auto", event, user_id=user_id)
        # Save each closed trade to the user's run history for the Results page.
        if event.get("type") == "exit" and event.get("trade"):
            await _save_single_trade_to_history(event["trade"], "live", run_name=run_id, explicit_user_id=user_id)

    # Store engine and start task
    live_bucket[run_id] = engine
    live_task_bucket[run_id] = _supervise_engine_task(
        asyncio.create_task(engine.start(callback=broadcast)), engine, run_id=run_id
    )

    # Persist config + state immediately so it survives server restarts
    engine.session_date = _ist_today()
    engine._save_state()

    alerter.alert("Engine Started", f"Strategy: {run_id}\nMode: Auto (LIVE)", level="info")
    return {"status": "started", "run_id": run_id, "message": "Auto trading started with REAL orders"}


@app.post("/api/live/stop")
async def live_stop(request: Request):
    user_id = _request_user_id(request)
    live_bucket = _registry_bucket(live_engines, user_id)
    live_task_bucket = _registry_bucket(_live_tasks, user_id)
    stopped_engines = _load_stopped_engines(user_id)
    body = {}
    try:
        body = await request.json()
    except Exception:
        pass
    run_id = body.get("run_id", "")

    # If no run_id, stop the first (or only) running engine
    if not run_id:
        running = [rid for rid, e in live_bucket.items() if e.running]
        if running:
            run_id = running[0]
        else:
            return {"status": "not_running"}

    engine = live_bucket.get(run_id)
    if not engine:
        return {"status": "not_found", "run_id": run_id}

    if getattr(engine, "positions", None):
        sqoff = await _square_off_live_engine_positions(engine, user_id, run_id, reason="ENGINE_STOP")
        if not sqoff.get("ok"):
            return {
                "status": sqoff.get("status", "error"),
                "run_id": run_id,
                "message": "Live engine stop aborted because broker square-off is not fully confirmed yet.",
                "square_off": sqoff,
                "engine_status": engine.get_status(),
            }

    # Capture results AFTER any required square-off and BEFORE stopping
    status_before = engine.get_status()

    engine.stop()
    task = live_task_bucket.pop(run_id, None)
    if task and not task.done():
        task.cancel()
        try:
            await task
        except asyncio.CancelledError:
            pass
    live_bucket.pop(run_id, None)

    # Delete state file so engine doesn't auto-restore on next startup
    engine._delete_state_file()

    # Persist live run to the user's history (same as paper)
    await _save_live_run_to_history(status_before, explicit_user_id=getattr(engine, "_user_id", None))

    # Keep snapshot on Live page so panel persists after stop
    status_before["running"] = False
    status_before["run_id"] = run_id
    status_before["mode"] = "auto"
    stopped_engines[_engine_snapshot_key(run_id, "auto")] = status_before
    _save_stopped_engines(user_id)
    _alert_state.pop(_alert_state_key(user_id, run_id), None)

    pnl = round(status_before.get("total_pnl", 0), 2)
    trades = len(status_before.get("closed_trades", []))
    alerter.alert(
        "Engine Stopped",
        f"Strategy: {run_id}\nMode: Auto (LIVE)\nTrades: {trades}\nTotal P&L: \u20b9{pnl:.2f}",
        level="warn",
    )

    return {"status": "stopped", "run_id": run_id}


@app.get("/api/live/status")
async def live_status(request: Request, run_id: str = ""):
    """Get live engine status. If run_id empty, returns first running engine."""
    user_id = _request_user_id(request)
    live_bucket = _registry_bucket(live_engines, user_id)
    if run_id and run_id in live_bucket:
        return live_bucket[run_id].get_status()
    # Return first running engine's status
    for rid, engine in live_bucket.items():
        if engine.running:
            return engine.get_status()
    # Nothing running — return idle status
    return {
        "running": False,
        "run_id": "",
        "mode": "auto",
        "in_trade": False,
        "positions": [],
        "closed_trades": [],
        "total_pnl": 0,
        "trades_today": 0,
        "strategy_name": "",
        "instrument": "",
        "current_candle": {},
        "current_indicators": {},
        "event_log": [],
    }


def _one_row_per_trade(runs: list, history: list) -> list:
    """One trade, one row. The book's row, with Dhan's money once Dhan has it.

    The desk's ledger prints every book's own closed list AND the whole broker
    record underneath it, and nothing reconciled the two — so a trade the engine
    had booked appeared twice: once as its own row with the exit reason and the
    chart, and again tagged "old closed" from the account (Phil, 2026-09-10:
    "I have said I need one entry but why you are making 2?").

    They are the same trade, and each half knows something the other does not.
    The engine's row knows WHY it closed and can draw itself. The account's row
    knows what it really cost, but only after Dhan books the day's charges
    overnight — until then its P&L is gross, which is why it read ₹1,879 beside
    the engine's ₹1,763 for one 130-lot PE.

    So: keep the book's row, drop the account's copy, and when the account has
    settled the charges, take its net for the P&L column ("once the charges
    updates on Dhan, update the PL column on the next day"). Matched on the day
    and the option side, and only where each side of the match is unambiguous —
    a book takes one trade a day, and a day with two of them is left alone
    rather than guessed at.
    """
    # ONLY BOOKS WHOSE ORDERS REACHED THE BROKER. The broker's record holds real
    # fills, and a paper book's trades never got there — so a paper trade can
    # never be the account row's twin. `real_orders` is the same field the
    # desk's LIVE/PAPER split and the LIVE badge read. Matching paper books did
    # three wrong things at once on 2026-09-10: the paper book My_First_Run_CE
    # had a CE on 09-03 for −₹2,936.31, so the REAL account CE of −₹1,740.25
    # was paired with it and deleted from the table; the paper trade's own P&L
    # was overwritten with the broker's; and the difference, +₹1,196, was booked
    # onto the live CE book. Meanwhile three PE books had traded on 09-10 (one
    # live, two paper), so the genuine duplicate was waved through as ambiguous.
    own_by_key: dict[tuple, list] = defaultdict(list)
    for run in runs:
        side = str(run.get("side") or "").upper()
        if not side or not run.get("real_orders"):
            continue
        for trade in run.get("recent") or []:
            own_by_key[(str(trade.get("entry_time") or "")[:10], side)].append((run, trade))

    account_by_key: dict[tuple, list] = defaultdict(list)
    for row in history or []:
        account_by_key[(str(row.get("date") or ""), str(row.get("side") or "").upper())].append(row)

    settled = []
    for key, rows in account_by_key.items():
        mine = own_by_key.get(key) or []
        if not mine:
            settled.extend(rows)  # the account knows of a day no live book does
            continue
        if len(mine) != 1 or len(rows) != 1:
            settled.extend(rows)  # ambiguous — show both rather than pick wrong
            continue
        # The same trade. The book's row survives; the account's money wins once
        # the broker has actually booked the charges — and the correction goes
        # to THE book that matched, never to every book on that side.
        run, trade = mine[0]
        moved = _settle_against_account([trade], key[1], rows)
        if moved:
            # `booked_pnl` comes from the WHOLE closed list, of which `recent` is
            # the tail, so it is nudged by what changed rather than re-added.
            run["booked_pnl"] = round(float(run.get("booked_pnl", 0) or 0) + moved, 2)

    settled.sort(key=lambda r: str(r.get("date") or ""), reverse=True)
    return settled


def _with_account_history(status: dict, account_rows: list) -> dict:
    """Fold a live book's earlier trades into the status the Live page reads.

    The panel builds its Completed Trades table from `closed_trades` and its
    headline from `total_pnl`, so both move together or the page disagrees with
    itself -- ₹0.00 above a table of real losses is worse than either half.
    """
    if not isinstance(status, dict):
        return status
    own = list(status.get("closed_trades") or [])
    side = _book_option_side(status.get("strategy") or {})
    # The same settlement the CE + PE desk applies, so the two pages cannot
    # disagree about what one trade made.
    settled_by = _settle_against_account(own, side, account_rows)
    borrowed = _account_rows_this_book_is_missing(status.get("strategy") or {}, own, account_rows)
    if not borrowed and not settled_by:
        return status
    borrowed_pnl = sum(float(row.get("pnl", 0) or 0) for row in borrowed)
    return {
        **status,
        "closed_trades": borrowed + own,
        "total_pnl": round(float(status.get("total_pnl", 0) or 0) + borrowed_pnl + settled_by, 2),
    }


def _settle_against_account(own_rows: list, side: str, account_rows: list) -> float:
    """Replace an engine's estimated P&L with the broker's, once Dhan has it.

    An engine books a trade the moment it closes, costing it from the statutory
    schedule. Dhan books the day's real charges overnight. Until then the two
    disagree by a few rupees -- ₹1,763.21 against ₹1,798.44 on 2026-09-10 -- and
    the broker's is the one that is true (Phil: "once the charges updates on
    Dhan, update the PL column on the next day").

    Mutates the rows in place and returns how much the total moved by, so a
    caller can nudge a headline it computed from a longer list.
    """
    if not side or not own_rows:
        return 0.0
    mine_by_day: dict[str, list] = defaultdict(list)
    for trade in own_rows:
        mine_by_day[str(trade.get("entry_time") or "")[:10]].append(trade)

    moved = 0.0
    for row in account_rows or []:
        if str(row.get("side") or "").upper() != side or not row.get("costs_known"):
            continue
        mine = mine_by_day.get(str(row.get("date") or "")) or []
        if len(mine) != 1:
            continue  # a day with two trades is left alone rather than guessed at
        was = float(mine[0].get("pnl", 0) or 0)
        mine[0]["pnl"] = row.get("pnl")
        mine[0]["gross_pnl"] = row.get("gross_pnl")
        mine[0]["charges"] = row.get("charges")
        mine[0]["settled_by_broker"] = True
        moved += float(mine[0]["pnl"] or 0) - was
    return round(moved, 2)


def _account_rows_this_book_is_missing(strategy: dict, own_closed: list, account_rows: list) -> list:
    """This book's earlier trades, from the broker's record, as engine trades.

    A book's own list only covers what it has closed since the engine last
    started, so CE_SL15_NoMonTue read "0 trades" and ₹0.00 while its real CE
    trade of 2026-09-03 sat in the account table lower down the same page.

    These rows are NOT proof. The broker records the fill, not the strategy that
    placed it, and Gap Carry has traded real NIFTY options since 02-Sep-2026 --
    so a CE row from the account is probably this book and cannot be shown as
    certainly this book. Hence: the option side must match and be unambiguous, a
    two-sided book borrows nothing, and a day the engine has its own record for
    is never touched. Where the book knows, the book wins.

    Shaped like an engine trade rather than an account row, because the count,
    the booked total and the table are all derived from one list -- so a
    borrowed row has to look like the thing that list holds. `from_account`
    marks it, and it carries no `id`, so it offers no journal chart it cannot
    draw.
    """
    side = _book_option_side(strategy)
    if not side:
        return []
    covered = {str(t.get("entry_time") or "")[:10] for t in own_closed or []}
    borrowed = [
        {
            "trading_symbol": row.get("symbol"),
            "entry_time": row.get("entry_time"),
            "exit_time": row.get("exit_time"),
            "transaction_type": "BUY",
            "option_type": side,
            "entry_premium": row.get("entry_premium"),
            "exit_premium": row.get("exit_premium"),
            "quantity": row.get("quantity"),
            "pnl": row.get("pnl"),
            "gross_pnl": row.get("gross_pnl"),
            "charges": row.get("charges"),
            "exit_reason": "from the account",
            "from_account": True,
        }
        for row in account_rows or []
        if row.get("side") == side and row.get("date") not in covered
    ]
    # Oldest first, matching the engine's own list, which the desk reverses.
    borrowed.sort(key=lambda r: str(r.get("entry_time") or ""))
    return borrowed


def _book_option_side(strategy: dict) -> str:
    """CE or PE, from the book's own legs. Empty when it trades both."""
    sides = {str((leg or {}).get("option_type") or "").upper() for leg in (strategy or {}).get("legs") or []}
    sides.discard("")
    return sides.pop() if len(sides) == 1 else ""


# The CE and PE books went live on this date. The account traded NIFTY options
# long before it -- April carries a dozen rows from other activity entirely --
# and none of that can belong to these books, so none of it belongs on their
# desk (Phil, 2026-09-10: "It populated all trades some months old back").
_CEPE_LIVE_FROM = "2026-09-03"


async def _account_option_history(user_id: int, limit: int = 60) -> list[dict]:
    """Closed NIFTY option trades from the BROKER ACCOUNT, newest first.

    An engine's closed_trades list is per-run and starts empty on every fresh
    deploy, so a re-deployed book shows nothing it did last week. trade_history
    is the durable record -- rebuilt FIFO from the broker's own fills -- and
    survives any restart.

    It carries NO strategy attribution. Gap Carry has traded real NIFTY options
    since 02-Sep-2026 as well, so a row here cannot be claimed for the CE or PE
    book; it is split by CE/PE only so the desk's own filter still works, and
    the desk labels these rows as coming from the account rather than the book.
    """
    try:
        history = await _db_mod.list_trade_history(int(user_id))
    except Exception:
        return []
    rows: list[dict] = []
    for trade_date, payload in (history or {}).items():
        if str(trade_date) < _CEPE_LIVE_FROM:
            continue
        if str((payload or {}).get("mode", "")) != "real":
            continue
        for leg in (payload or {}).get("details") or []:
            symbol = str(leg.get("symbol") or "")
            upper = symbol.upper()
            if "NIFTY" not in upper:
                continue
            if "PE" in upper.split() or "PUT" in upper or upper.endswith("-PE"):
                side = "PE"
            elif "CE" in upper.split() or "CALL" in upper or upper.endswith("-CE"):
                side = "CE"
            else:
                continue
            gross = round(float(leg.get("pnl", 0) or 0), 2)
            costs = round(float(leg.get("total_costs", 0) or 0), 2)
            rows.append(
                {
                    "date": str(trade_date),
                    "entry_time": str(leg.get("first_buy") or ""),
                    "exit_time": str(leg.get("last_sell") or ""),
                    "side": side,
                    "symbol": symbol,
                    "quantity": leg.get("qty"),
                    "entry_premium": leg.get("buy_avg"),
                    "exit_premium": leg.get("sell_avg"),
                    # trade_history stores GROSS per leg -- the day's net_pnl is
                    # pnl minus total_costs. The engine's own rows are already
                    # net, so these are netted here or the ledger would mix the
                    # two in one column and overstate the older half.
                    "gross_pnl": gross,
                    "charges": costs,
                    "pnl": round(gross - costs, 2),
                    "costs_known": costs > 0,
                    "from_account": True,
                }
            )
    rows.sort(key=lambda r: r["date"], reverse=True)
    return rows[:limit]


@app.get("/api/live/runs")
async def live_runs(request: Request):
    """Every strategy-builder run this user has, in one slim summary.

    `/api/live/status` answers for ONE engine -- the first one running -- which
    is fine for a page showing a single run and useless for a desk showing the
    CE and PE books side by side. This returns both, and deliberately leaves out
    the two fields that make a status heavy: the event log and the full closed
    trade list. A console polls this every few seconds; the detail already has
    its own endpoints (`/api/live/status`, `/api/live/trade-chart`), and
    cascade/status shipping 3.75MB every three seconds is a mistake this repo
    has already made once.
    """
    user_id = _request_user_id(request)
    # BOTH registries. The strategy builder deploys into `live_engines`, and a
    # paper deployment of the same strategy lands in `paper_engines`; a desk
    # that reads only the first shows two books when five are loaded.
    pairs = [(rid, eng, True) for rid, eng in _registry_bucket(live_engines, user_id).items()]
    pairs += [(rid, eng, False) for rid, eng in _registry_bucket(paper_engines, user_id).items()]
    runs = []
    for run_id, engine, is_live_registry in pairs:
        try:
            strategy = getattr(engine, "strategy", None) or {}
            legs = strategy.get("legs") or []
            leg = legs[0] if legs else {}
            open_legs = [p for p in engine.positions if p.get("status") != "closed"]
            # DELIBERATELY NOT BORROWED FROM THE ACCOUNT HERE. This desk already
            # receives the whole account record as `history` below and renders it
            # in its own ALL TIME table, so adding those rows to a book's list
            # too printed every trade twice -- once "from the account" and once
            # tagged "old closed" (Phil, 2026-09-10: "I am seeing a duplicate
            # here in this Trading -> strategies -> CE PE"). The Live page has no
            # such table, which is why the borrowing belongs there and only
            # there. See `_with_account_history` on /api/engines/all.
            closed = list(engine.closed_trades or [])
            runs.append(
                {
                    "run_id": run_id,
                    "name": strategy.get("run_name") or run_id,
                    "running": bool(engine.running),
                    "mode": getattr(engine, "mode", ""),
                    "real_orders": bool(
                        is_live_registry
                        and str((getattr(engine, "deploy_config", None) or {}).get("order_type", "")).lower() == "auto"
                    ),
                    "side": str(leg.get("option_type") or "").upper(),
                    "lots": leg.get("lots"),
                    "expiry_day_lots": leg.get("expiry_day_lots") or 0,
                    # The ladder is strategy-level, not per-leg: one rung count
                    # for the whole run. Shown on the desk so the size a book is
                    # trading is never a mystery.
                    "compound_step_pct": float(strategy.get("compound_step_pct", 0) or 0),
                    "compound_max_lots": int(strategy.get("compound_max_lots", 0) or 0),
                    "sl_pct": leg.get("sl_pct"),
                    "strike_rule": f"{leg.get('strike_type', '')} {leg.get('strike_value', '')}".strip(),
                    "in_trade": bool(engine.in_trade),
                    "trades_today": int(engine.trades_today or 0),
                    "daily_pnl": round(float(engine.daily_pnl or 0), 2),
                    "closed_count": len(closed),
                    "booked_pnl": round(sum(float(t.get("pnl", 0) or 0) for t in closed), 2),
                    "open_legs": [
                        {
                            "leg": p.get("leg_num"),
                            "symbol": p.get("trading_symbol") or p.get("display_symbol"),
                            "strike": p.get("strike"),
                            "option_type": p.get("option_type"),
                            "quantity": p.get("quantity"),
                            "entry_premium": p.get("entry_premium"),
                            "current_premium": p.get("current_premium"),
                            "unrealized_pnl": round(float(p.get("unrealized_pnl", 0) or 0), 2),
                            "sl_order_id": p.get("sl_order_id"),
                            "entry_time": str(p.get("entry_time") or ""),
                        }
                        for p in open_legs
                    ],
                    # The last few closed trades, enough for a table without
                    # shipping the whole book on every poll.
                    "recent": [
                        {
                            "id": t.get("id"),
                            # A live trade names its contract `trading_symbol`,
                            # a paper trade names it `symbol` — so every paper
                            # row on the desk read "—" in the Contract column.
                            "symbol": t.get("trading_symbol") or t.get("display_symbol") or t.get("symbol"),
                            "entry_time": str(t.get("entry_time") or ""),
                            "exit_time": str(t.get("exit_time") or ""),
                            "entry_premium": t.get("entry_premium"),
                            "exit_premium": t.get("exit_premium"),
                            "quantity": t.get("quantity"),
                            "exit_reason": t.get("exit_reason"),
                            "pnl": t.get("pnl"),
                            # pnl is already NET (engine: gross - charges). The
                            # breakdown travels with it so the desk can show what
                            # was deducted instead of leaving it implied.
                            "gross_pnl": t.get("gross_pnl"),
                            "charges": t.get("charges"),
                            "why": LiveEngine._conditions_that_fired(t.get("exit_why")),
                        }
                        for t in closed[-25:]
                    ],
                    "manual_intervention_required": bool(getattr(engine, "manual_intervention_required", False)),
                    "unprotected_legs": len(engine._unprotected_legs()) if hasattr(engine, "_unprotected_legs") else 0,
                    "last_event": (engine.event_log[-1]["message"] if getattr(engine, "event_log", None) else ""),
                    "current_spot": getattr(engine, "current_spot", 0),
                }
            )
        except Exception as exc:  # one broken engine must not blank the desk
            _logger.warning("[LIVE RUNS] could not read %s: %s", run_id, exc)
            runs.append(
                {
                    "run_id": run_id,
                    "name": run_id,
                    "error": str(exc),
                    "running": bool(getattr(engine, "running", False)),
                    "real_orders": False,
                    "side": "",
                    "lots": None,
                    "trades_today": 0,
                    "daily_pnl": None,
                    "booked_pnl": None,
                    "closed_count": 0,
                    "open_legs": [],
                    "recent": [],
                    "unprotected_legs": 0,
                    "last_event": "",
                }
            )
    runs.sort(key=lambda r: (r.get("side") != "CE", r.get("name", "")))
    history = _one_row_per_trade(runs, await _account_option_history(user_id))
    return {
        "status": "ok",
        "runs": runs,
        "count": len(runs),
        "booked_total": round(sum(float(r.get("booked_pnl", 0) or 0) for r in runs), 2),
        "day_total": round(sum(float(r.get("daily_pnl", 0) or 0) for r in runs), 2),
        # Everything the account closed that a book has no record of. A fresh
        # deploy wipes each engine's own list; this one outlives it.
        "history": history,
    }


@app.get("/api/live/index-chart")
async def live_index_chart(request: Request, instrument: str = "26000", timeframe: str = "5m", book: str = "all"):
    """The index itself, on the chart standard every entry chart already uses.

    Both books on the CE + PE desk read the same NIFTY chart -- one buys above
    its 17-EMA, the other below the CPR's bottom -- so the desk wants ONE chart
    of the underlying rather than one per book. The entry chart draws the
    contract that was bought and only exists while a position does; this draws
    the index whether anything is open or not.

    Same payload as /api/live/entry-chart so the same renderer draws it, and the
    same `_chart_session_analytics` for the pivots and the 20-EMA -- there is one
    chart vocabulary on this page and this does not add a second.
    """
    _user, broker_client, _source = await _request_broker_context(request)
    if broker_client is None:
        raise HTTPException(status_code=503, detail="A broker connection is needed to load the candles.")
    candle_type = {"5m": "5", "15m": "15", "1h": "60"}.get(str(timeframe).lower())
    if candle_type is None:
        raise HTTPException(status_code=400, detail="Charts are 5m, 15m or 1h.")
    info = INSTRUMENT_MAP.get(str(instrument)) or {}
    if not info:
        raise HTTPException(status_code=400, detail=f"Unknown instrument {instrument!r}.")
    today = datetime.now(IST).date()
    from_date = (today - timedelta(days=4 if candle_type != "60" else 10)).isoformat()
    try:
        frame = await asyncio.to_thread(
            broker_client.get_historical_data,
            security_id=str(info.get("dhan_id") or "13"),
            exchange_segment=str(info.get("dhan_seg") or "IDX_I"),
            instrument_type=str(info.get("dhan_type") or "INDEX"),
            from_date=from_date,
            to_date=today.isoformat(),
            candle_type=candle_type,
        )
    except Exception as exc:
        raise HTTPException(status_code=502, detail=f"Index candle request failed: {exc}") from exc
    if frame is None or frame.empty:
        raise HTTPException(status_code=404, detail=f"No {timeframe} candles returned for {info.get('name')}.")

    candles = []
    for timestamp, row in frame.iterrows():
        stamp = _scalp_option_chart_timestamp(timestamp)
        if stamp is None:
            continue
        candles.append(
            {
                "t": stamp,
                "o": round(float(row["open"]), 2),
                "h": round(float(row["high"]), 2),
                "l": round(float(row["low"]), 2),
                "c": round(float(row["close"]), 2),
            }
        )
    if not candles:
        raise HTTPException(status_code=404, detail="Index candles contained no usable timestamps")

    analytics = _chart_session_analytics(candles)
    spot = candles[-1]["c"]
    return {
        "status": "ok",
        "timeframe": str(timeframe).lower(),
        "is_open": True,
        "instrument": {
            "underlying": str(info.get("name") or "NIFTY 50"),
            "security_id": str(info.get("dhan_id") or "13"),
        },
        "candles": candles,
        "entries": [],
        "exits": [],
        # The pivots the header promises: CPR P/BC/TC, R1-R4 and S1-S5 come
        # from _chart_session_analytics, and LAST is drawn on top of them.
        # Taking only ["overlays"] here left the chart with the 20-EMA alone.
        "lines": analytics["lines"]
        + [{"label": "LAST", "price": spot, "color": "#e2e8f0", "dash": [2, 3], "width": 1.2, "opacity": 0.95}],
        "overlays": analytics["overlays"] + _supertrend_overlay_lines(candles, book),
        "live_price": spot,
    }


@app.get("/api/live/entry-chart")
async def live_entry_chart(request: Request, run_id: str = "", timeframe: str = "5m"):
    """The chart of the contract this run actually entered — scalp's standard.

    Phil (2026-08-13): the run page should show the entered option the way the
    scalp desk does — CPR, R1-R4/S1-S5, 20-EMA, entry mark, stop and target
    levels and the live premium as a dotted line. Works for the OPEN position
    first, and falls back to the most recent closed trade so the chart is
    still there to study after the exit. Paper and live runs alike.
    """
    user_id = _request_user_id(request)

    def _pick(engine):
        for pos in getattr(engine, "positions", []) or []:
            if pos.get("status") != "closed" and int(pos.get("strike") or 0) > 0:
                return pos, True
        for trade in reversed(getattr(engine, "closed_trades", []) or []):
            if int(trade.get("strike") or 0) > 0:
                return trade, False
        return None, False

    engine = None
    for bucket in (_registry_bucket(live_engines, user_id), _registry_bucket(paper_engines, user_id)):
        if run_id and run_id in bucket:
            engine = bucket[run_id]
            break
        if engine is None:
            for eng in bucket.values():
                if getattr(eng, "running", False):
                    engine = eng
                    break
    if engine is None:
        raise HTTPException(status_code=404, detail="No running engine found for this run")

    position, is_open = _pick(engine)
    if not position:
        raise HTTPException(status_code=404, detail="This run has not entered a trade yet")

    underlying = str(position.get("underlying") or getattr(engine, "instrument", "") or "NIFTY").strip().upper()
    strike = int(position.get("strike") or 0)
    expiry = str(position.get("expiry") or "").strip()
    option_type = str(position.get("option_type") or "").strip().upper()
    if strike <= 0 or option_type not in {"CE", "PE"}:
        raise HTTPException(status_code=422, detail="The entered contract is incomplete on this engine")

    security_id = await asyncio.to_thread(ScripMaster.lookup, underlying, strike, expiry, option_type)
    if not security_id:
        raise HTTPException(status_code=404, detail="Entered contract is unavailable in the current Scrip Master")

    broker_client = getattr(engine, "dhan", None)
    if broker_client is None:
        _, broker_client, _ = await _request_broker_context(request)
    if not broker_client:
        raise HTTPException(status_code=503, detail="Broker connection is required to load the entry chart")

    tf = str(timeframe or "5m").lower()
    candle_type = {"5m": "5", "15m": "15", "1h": "60"}.get(tf, "5")
    tf = {"5": "5m", "15": "15m", "60": "1h"}[candle_type]
    today = datetime.now(IST).date()
    from_date = (today - timedelta(days=4 if candle_type != "60" else 10)).isoformat()
    exchange_segment = "BSE_FNO" if underlying == "SENSEX" else "NSE_FNO"
    try:
        frame = await asyncio.to_thread(
            broker_client.get_historical_data,
            security_id=str(security_id),
            exchange_segment=exchange_segment,
            instrument_type="OPTIDX",
            from_date=from_date,
            to_date=today.isoformat(),
            candle_type=candle_type,
        )
    except Exception as exc:
        raise HTTPException(status_code=502, detail=f"Entry-chart candle request failed: {exc}") from exc
    if frame is None or frame.empty:
        raise HTTPException(status_code=404, detail="No intraday candles returned for the entered contract")

    candles = []
    for timestamp, row in frame.iterrows():
        stamp = _scalp_option_chart_timestamp(timestamp)
        if stamp is None:
            continue
        candles.append(
            {
                "t": stamp,
                "o": round(float(row["open"]), 4),
                "h": round(float(row["high"]), 4),
                "l": round(float(row["low"]), 4),
                "c": round(float(row["close"]), 4),
            }
        )
    if not candles:
        raise HTTPException(status_code=404, detail="Entry-chart candles contained no usable timestamps")

    analytics = _chart_session_analytics(candles)
    entry_time = _scalp_option_chart_timestamp(position.get("entry_time"))
    entry_price = float(position.get("entry_premium") or 0)
    exit_time = _scalp_option_chart_timestamp(position.get("exit_time"))
    exit_price = float(position.get("exit_premium") or 0)
    lines = list(analytics["lines"])
    for label, key, color in (("STOP", "sl_premium", "#ef4444"), ("TARGET", "target_premium", "#10b981")):
        level = float(position.get(key) or 0)
        if level > 0:
            lines.insert(
                0, {"label": label, "price": level, "color": color, "dash": [6, 3], "width": 1.2, "opacity": 0.95}
            )
    live_premium = float(position.get("current_premium") or 0) if is_open else 0.0
    if live_premium > 0:
        lines.append(
            {"label": "LIVE", "price": live_premium, "color": "#e2e8f0", "dash": [2, 3], "width": 1.2, "opacity": 0.95}
        )
    return {
        "status": "ok",
        "timeframe": tf,
        "is_open": is_open,
        "instrument": {
            "underlying": underlying,
            "strike": strike,
            "option_type": option_type,
            "expiry": expiry,
            "security_id": str(security_id),
        },
        "candles": candles,
        "entries": ([{"t": entry_time, "price": entry_price}] if entry_time and entry_price > 0 else []),
        "exits": (
            [{"t": exit_time, "price": exit_price, "pnl": float(position.get("pnl") or 0)}]
            if not is_open and exit_time and exit_price > 0
            else []
        ),
        "lines": lines,
        "overlays": analytics["overlays"],
        "live_price": live_premium,
    }


def _live_run_history_trades(run_id: str) -> list[dict]:
    """Every trade a run has ever closed, from its persistent history file.

    Both engines write `paper_history_<run>.json` / `live_history_<run>.json`
    beside the state file (see engine/paper_trading.py `_save_trade_history`),
    so a run that has been STOPPED -- or ended by a restart -- still has its
    trades reachable for the journal. Missing file = no history, not an error.
    """
    safe = "".join(c if c.isalnum() or c in ("-", "_") else "_" for c in str(run_id or ""))
    out: list[dict] = []
    for prefix in ("paper_history_", "live_history_"):
        path = (
            os.path.join(_HERE, f"{prefix}{safe}.json") if safe else os.path.join(_HERE, f"{prefix.rstrip('_')}.json")
        )
        try:
            if os.path.exists(path):
                with open(path, "r", encoding="utf-8") as handle:
                    rows = json.load(handle)
                if isinstance(rows, list):
                    out.extend(r for r in rows if isinstance(r, dict))
        except Exception as exc:
            _logger.warning("[LIVE JOURNAL] history %s unreadable: %s", path, exc)
    return out


@app.get("/api/live/trade-chart")
async def live_trade_chart(request: Request, run_id: str = "", trade_id: str = "", timeframe: str = "5m"):
    """ONE trade's chart, frozen at its exit, with the WHY -- the journal view.

    Phil, 2026-08-17: "a journal chart on every live trade ... where, when,
    why the trade was taken and exited, with all CPR and indicators ... a
    frozen chart like CryptoForge." /api/live/entry-chart shows the OPEN (or
    latest) contract to today; this picks a SPECIFIC trade by id from the
    running engine or the run's history file, fetches candles from before the
    entry TO THE EXIT and stops there -- CryptoForge's `end_ts` freeze, so a
    trade viewed days later still shows the market as it was -- and returns
    the entry/exit `why` the engines now record. Same renderer, same
    CPR/R1-R4/S1-S5/20-EMA analytics as the entry chart.
    """
    user_id = _request_user_id(request)
    engine = None
    for bucket in (_registry_bucket(live_engines, user_id), _registry_bucket(paper_engines, user_id)):
        if run_id and run_id in bucket:
            engine = bucket[run_id]
            break

    # The trade: engine's closed list first (freshest), then the history file.
    candidates: list[dict] = []
    if engine is not None:
        candidates.extend(getattr(engine, "closed_trades", []) or [])
        candidates.extend(p for p in (getattr(engine, "positions", []) or []) if p.get("status") == "closed")
    candidates.extend(_live_run_history_trades(run_id))
    trade = None
    if trade_id:
        for row in candidates:
            if str(row.get("id")) == str(trade_id):
                trade = row
                break
    if trade is None and candidates:
        trade = candidates[-1]
    if trade is None:
        raise HTTPException(status_code=404, detail="No closed trade with that id on this run")

    underlying = str(trade.get("underlying") or getattr(engine, "instrument", "") or "NIFTY").strip().upper()
    if underlying.isdigit():
        underlying = {
            "26000": "NIFTY",
            "26009": "BANKNIFTY",
            "26017": "FINNIFTY",
            "26037": "MIDCPNIFTY",
            "1": "SENSEX",
        }.get(underlying, "NIFTY")
    strike = int(float(trade.get("strike") or 0))
    expiry = str(trade.get("expiry") or "").strip()
    option_type = str(trade.get("option_type") or "").strip().upper()
    if strike <= 0 or option_type not in {"CE", "PE"}:
        raise HTTPException(status_code=422, detail="This trade record has no usable contract")

    entry_ts = _scalp_option_chart_timestamp(trade.get("entry_time"))
    exit_ts = _scalp_option_chart_timestamp(trade.get("exit_time"))
    if not entry_ts:
        raise HTTPException(status_code=422, detail="This trade record has no entry time")

    security_id = await asyncio.to_thread(ScripMaster.lookup, underlying, strike, expiry, option_type)
    if not security_id:
        raise HTTPException(status_code=404, detail="This trade's contract is no longer in the Scrip Master (expired?)")

    broker_client = getattr(engine, "dhan", None) if engine is not None else None
    if broker_client is None:
        _, broker_client, _ = await _request_broker_context(request)
    if not broker_client:
        raise HTTPException(status_code=503, detail="Broker connection is required to load the trade chart")

    tf = str(timeframe or "5m").lower()
    candle_type = {"5m": "5", "15m": "15", "1h": "60"}.get(tf, "5")
    tf = {"5": "5m", "15": "15m", "60": "1h"}[candle_type]
    entry_day = datetime.fromtimestamp(entry_ts, IST).date()
    # FROZEN WINDOW: from a few sessions before the entry (so CPR has its
    # prior day and the EMA has warm-up) to the EXIT day -- never "today".
    end_day = datetime.fromtimestamp(exit_ts, IST).date() if exit_ts else entry_day
    from_date = (entry_day - timedelta(days=4 if candle_type != "60" else 10)).isoformat()
    exchange_segment = "BSE_FNO" if underlying == "SENSEX" else "NSE_FNO"
    try:
        frame = await asyncio.to_thread(
            broker_client.get_historical_data,
            security_id=str(security_id),
            exchange_segment=exchange_segment,
            instrument_type="OPTIDX",
            from_date=from_date,
            to_date=end_day.isoformat(),
            candle_type=candle_type,
        )
    except Exception as exc:
        raise HTTPException(status_code=502, detail=f"Trade-chart candle request failed: {exc}") from exc
    if frame is None or frame.empty:
        raise HTTPException(status_code=404, detail="No candles returned for this trade's contract")

    candles = []
    for timestamp, row in frame.iterrows():
        stamp = _scalp_option_chart_timestamp(timestamp)
        if stamp is None:
            continue
        # The freeze: nothing after the exit bar. A little runway past the exit
        # is kept so the exit mark is not the last pixel on the canvas.
        if exit_ts and stamp > exit_ts + 6 * {"5": 300, "15": 900, "60": 3600}[candle_type]:
            continue
        candles.append(
            {
                "t": stamp,
                "o": round(float(row["open"]), 4),
                "h": round(float(row["high"]), 4),
                "l": round(float(row["low"]), 4),
                "c": round(float(row["close"]), 4),
            }
        )
    if not candles:
        raise HTTPException(status_code=404, detail="Trade-chart candles contained no usable timestamps")

    analytics = _chart_session_analytics(candles)
    entry_price = float(trade.get("entry_premium") or 0)
    exit_price = float(trade.get("exit_premium") or 0)
    lines = list(analytics["lines"])
    for label, key, color in (("STOP", "sl_premium", "#ef4444"), ("TARGET", "target_premium", "#10b981")):
        level = float(trade.get(key) or 0)
        if level > 0:
            lines.insert(
                0, {"label": label, "price": level, "color": color, "dash": [6, 3], "width": 1.2, "opacity": 0.95}
            )

    entry_why = trade.get("entry_why") if isinstance(trade.get("entry_why"), dict) else None
    exit_why = trade.get("exit_why") if isinstance(trade.get("exit_why"), dict) else None

    # THE RULE THAT ENDED THE TRADE, on the chart of the trade it ended.
    # Phil, 2026-09-03: "I need the super trend indicator that cuts today's
    # trade to an exit.. I want that in the chart as well". CE_SL15 exits on
    # Supertrend(10, 2.7) over 3m NIFTY; it turned down at 10:36 and the engine
    # acted at the next 5m boundary, 10:45. Without it on the chart the exit
    # looks arbitrary.
    supertrend_overlay = None
    spec = _strategy_supertrend_spec(getattr(engine, "strategy", None))
    if spec:
        supertrend_overlay = await _index_supertrend_flips(
            broker_client, underlying, spec, from_date, end_day.isoformat(), until_ts=exit_ts
        )
    return {
        "status": "ok",
        "timeframe": tf,
        "is_open": False,
        "supertrend": supertrend_overlay,
        "frozen_at": exit_ts,
        "trade": {
            "id": trade.get("id"),
            "run_id": run_id,
            "symbol": trade.get("symbol"),
            "transaction_type": trade.get("transaction_type"),
            "quantity": trade.get("quantity"),
            "lots": trade.get("lots"),
            "entry_time": entry_ts,
            "exit_time": exit_ts,
            "entry_premium": entry_price,
            "exit_premium": exit_price,
            "entry_spot": trade.get("entry_spot"),
            "pnl": float(trade.get("pnl") or 0),
            "exit_reason": trade.get("exit_reason"),
        },
        "why": {"entry": entry_why, "exit": exit_why},
        "instrument": {
            "underlying": underlying,
            "strike": strike,
            "option_type": option_type,
            "expiry": expiry,
            "security_id": str(security_id),
        },
        "candles": candles,
        "entries": ([{"t": entry_ts, "price": entry_price}] if entry_price > 0 else []),
        "exits": (
            [{"t": exit_ts, "price": exit_price, "pnl": float(trade.get("pnl") or 0)}]
            if exit_ts and exit_price > 0
            else []
        ),
        "lines": lines,
        "overlays": analytics["overlays"],
        "live_price": 0.0,
    }


@app.get("/api/live/debug")
async def live_debug(request: Request, run_id: str = ""):
    """Deep diagnostic of live engine state — call when trades aren't triggering."""
    user_id = _request_user_id(request)
    live_bucket = _registry_bucket(live_engines, user_id)
    engine = None
    if run_id and run_id in live_bucket:
        engine = live_bucket[run_id]
    else:
        for e in live_bucket.values():
            if e.running:
                engine = e
                break
    if not engine:
        return {"error": "No live engine running", "engines": list(live_bucket.keys())}
    return engine.debug_engine_state()


@app.get("/api/live/trades/csv")
async def export_live_trades_csv(request: Request, run_id: str = ""):
    """Export live auto-trading trades to CSV"""
    import csv as csv_mod
    import io

    live_bucket = _registry_bucket(live_engines, _request_user_id(request))
    engine = live_bucket.get(run_id) if run_id else None
    if not engine:
        # Find first engine with trades
        for e in live_bucket.values():
            if e.closed_trades:
                engine = e
                break
    if not engine or not engine.closed_trades:
        raise HTTPException(status_code=404, detail="No live trades available")
    output = io.StringIO()
    fields = [
        "id",
        "leg_num",
        "transaction_type",
        "option_type",
        "strike",
        "entry_time",
        "exit_time",
        "entry_premium",
        "exit_premium",
        "lots",
        "lot_size",
        "pnl",
        "exit_reason",
        "entry_order_id",
        "exit_order_id",
    ]
    writer = csv_mod.DictWriter(output, fieldnames=fields, extrasaction="ignore")
    writer.writeheader()
    for t in engine.closed_trades:
        row = {k: (str(v) if k in ("entry_time", "exit_time") else v) for k, v in t.items() if k in fields}
        writer.writerow(row)
    output.seek(0)
    return StreamingResponse(
        iter([output.getvalue()]),
        media_type="text/csv",
        headers={"Content-Disposition": f"attachment; filename=live_trades_{datetime.now().strftime('%Y%m%d')}.csv"},
    )


# ── Paper Trading (Real Market Data) ──────────────────────────────
@app.post("/api/paper/start")
async def paper_start(payload: StrategyPayload, request: Request):
    """Start paper trading with real live market data"""
    try:
        return await _paper_start_impl(payload, _request_user_id(request))
    except Exception:
        _logger.exception(
            "[PAPER] Start failed request_id=%s",
            getattr(request.state, "request_id", "-"),
        )
        raise


async def _paper_start_impl(payload: StrategyPayload, user_id: int):
    paper_bucket = _registry_bucket(paper_engines, user_id)
    paper_task_bucket = _registry_bucket(_paper_tasks, user_id)
    stopped_engines = _load_stopped_engines(user_id)
    entry_conditions = payload.entry_conditions or DEFAULT_ENTRY_CONDITIONS
    exit_conditions = payload.exit_conditions or DEFAULT_EXIT_CONDITIONS
    contract = validate_strategy_contract(payload.indicators, entry_conditions, exit_conditions)
    normalized_indicators = contract["normalized_indicators"]
    if contract["errors"]:
        return {
            "status": "error",
            "message": "Strategy validation failed:\n- " + "\n- ".join(contract["errors"]),
            "validation": contract,
        }
    execution_timeframe = infer_execution_timeframe(normalized_indicators, entry_conditions, default=5)
    try:
        tf_spec = resolve_strategy_timeframe(
            normalized_indicators,
            default=execution_timeframe,
            execution_hint=execution_timeframe,
        )
    except ValueError as tf_err:
        return {"status": "error", "message": str(tf_err)}
    # Configure strategy — pass ALL fields needed for SL/TP/strike logic
    strategy_dict = {
        "strategy_id": int(payload.strategy_id or 0),
        "run_name": payload.run_name,
        # The folder the run was deployed from. The Running Now cards open the
        # saved strategy's folder from here; without it a run started with no
        # saved-strategy id (Phil's My_First_Run_PE, 2026-08-17) resolved to
        # nothing and the card printed a made-up "Intraday".
        "folder": str(payload.folder or "").strip(),
        "instrument": payload.instrument,
        "indicators": normalized_indicators,
        "max_trades_per_day": int(payload.max_trades_per_day or 1),
        "market_open": payload.market_open or "09:15",
        "market_close": payload.market_close or "15:25",
        "legs": payload.legs or [],
        "deploy_config": payload.deploy_config or {},
        "poll_interval": 10,  # Check every 10 seconds
        # Strategy-level SL/TP
        "lots": payload.lots,
        "lot_size": payload.lot_size,
        "stoploss_pct": payload.stoploss_pct,
        "stoploss_rupees": payload.stoploss_rupees,
        "sl_type": payload.sl_type,
        "target_profit_pct": payload.target_profit_pct,
        "target_profit_rupees": payload.target_profit_rupees,
        "tp_type": payload.tp_type,
        "initial_capital": payload.initial_capital,
        "execution_profile": payload.execution_profile,
        "spread_bps": payload.spread_bps,
        "entry_slippage_bps": payload.entry_slippage_bps,
        "exit_slippage_bps": payload.exit_slippage_bps,
        "enforce_capital": payload.enforce_capital,
        "capital_buffer_pct": payload.capital_buffer_pct,
        "sell_option_margin_per_lot": payload.sell_option_margin_per_lot,
        "max_daily_loss": payload.max_daily_loss,
        "skip_days_after_profit": int(payload.skip_days_after_profit or 0),
        "skip_profit_threshold_rupees": float(payload.skip_profit_threshold_rupees or 20000),
        "signal_cutoff_time": str(payload.signal_cutoff_time or "").strip(),
        "combined_sqoff_time": payload.combined_sqoff_time,
        "timeframe_minutes": tf_spec.requested,
        "fetch_timeframe_minutes": tf_spec.fetch,
    }
    strategy_dict["_user_id"] = user_id

    await _sync_saved_strategy_from_runtime(
        user_id,
        strategy_dict.get("strategy_id", 0),
        payload.model_dump(),
        entry_conditions,
        exit_conditions,
        source_label="paper start",
    )

    # Generate run_id from strategy name
    run_id = strategy_dict.get("run_name", "paper") or "paper"

    # Clear only the stopped snapshot for this exact engine identity
    stopped_engines.pop(_engine_snapshot_key(run_id, "paper"), None)
    _save_stopped_engines(user_id)

    # If an engine with same run_id exists, save its results before replacing
    old_engine = paper_bucket.get(run_id)
    if old_engine:
        try:
            old_status = old_engine.get_status()
            if old_engine.running:
                old_engine.stop()
                task = paper_task_bucket.pop(run_id, None)
                if task and not task.done():
                    task.cancel()
            await _save_paper_run_to_history(old_status, explicit_user_id=getattr(old_engine, "_user_id", None))
        except Exception as e:
            print(f"[PAPER] Failed to save old engine {run_id}: {e}")
        paper_bucket.pop(run_id, None)

    # Create a new engine instance for this strategy
    engine = PaperTradingEngine(dhan, run_id=run_id, state_dir=_engine_state_dir(user_id))
    engine.configure(
        strategy=strategy_dict,
        entry_conditions=entry_conditions,
        exit_conditions=exit_conditions,
    )
    engine._user_id = user_id

    # Inject WebSocket feed if available — starts WS + subscribes index
    if _market_feed and HAS_DHAN_FEED:
        instrument = strategy_dict.get("instrument", "26000")
        _market_feed.subscribe_index(instrument)
        if not _market_feed.is_running:
            _market_feed.start()
        engine.set_feed(_market_feed)

    # Set running IMMEDIATELY so UI never sees a stale "stopped" state
    engine.running = True
    engine.event_log = []
    engine.positions = []
    # Preserve historical closed trades so "Completed Trades" panel shows past results
    engine.closed_trades = engine._load_trade_history() if hasattr(engine, "_load_trade_history") else []
    engine.in_trade = False
    engine.trades_today = 0

    # Broadcast updates to WebSocket clients + Telegram alerts
    await _reset_alert_state_for_start(user_id, run_id, engine.closed_trades)

    async def broadcast(event: dict):
        await _broadcast_user_ws_json(user_id, {"source": "paper", "run_id": run_id, **event})
        await _check_trade_alerts(run_id, "Paper", event, user_id=user_id)
        # Save each closed trade to the user's run history for the Results page.
        if event.get("type") == "exit" and event.get("trade"):
            await _save_single_trade_to_history(event["trade"], "paper", run_name=run_id, explicit_user_id=user_id)

    # Store engine and start task
    paper_bucket[run_id] = engine
    paper_task_bucket[run_id] = asyncio.create_task(engine.start(callback=broadcast))

    # Persist NOW, the way live_start already does. The old engine's stop()
    # saved its dying in-memory config a few lines above, so until the new
    # engine writes something the file on disk still describes the run that was
    # just replaced -- and a restart in that window restores the OLD config and
    # silently undoes the deploy. That is exactly how PE_NoTarget kept coming
    # back on the custom 0/0/0 profile after being redeployed onto auto.
    engine.session_date = _ist_today()
    engine._save_state()

    alerter.alert("Engine Started", f"Strategy: {run_id}\nMode: Paper", level="info")
    return {"status": "started", "run_id": run_id, "message": "Paper trading started with LIVE market data"}


@app.post("/api/paper/stop")
async def paper_stop(request: Request):
    """Stop paper trading and persist results to runs.json"""
    user_id = _request_user_id(request)
    paper_bucket = _registry_bucket(paper_engines, user_id)
    paper_task_bucket = _registry_bucket(_paper_tasks, user_id)
    stopped_engines = _load_stopped_engines(user_id)
    body = {}
    try:
        body = await request.json()
    except Exception:
        pass
    run_id = body.get("run_id", "")

    # If no run_id, stop the first (or only) running engine
    if not run_id:
        running = [rid for rid, e in paper_bucket.items() if e.running]
        if running:
            run_id = running[0]
        else:
            return {"status": "not_running"}

    engine = paper_bucket.get(run_id)
    if not engine:
        return {"status": "not_found", "run_id": run_id}

    # Capture results BEFORE stopping (stop() may close positions)
    status_before = engine.get_status()

    engine.stop()

    task = paper_task_bucket.pop(run_id, None)
    if task and not task.done():
        task.cancel()
        try:
            await task
        except asyncio.CancelledError:
            pass

    paper_bucket.pop(run_id, None)

    # Delete state file so engine doesn't auto-restore on next startup
    engine._delete_state_file()

    # Save paper run to the user's history so it persists across restarts.
    await _save_paper_run_to_history(status_before, explicit_user_id=getattr(engine, "_user_id", None))

    # Keep snapshot on Live page so panel persists after stop
    status_before["running"] = False
    status_before["run_id"] = run_id
    status_before["mode"] = "paper"
    stopped_engines[_engine_snapshot_key(run_id, "paper")] = status_before
    _save_stopped_engines(user_id)
    _alert_state.pop(_alert_state_key(user_id, run_id), None)

    pnl = round(status_before.get("total_pnl", 0), 2)
    trades = len(status_before.get("closed_trades", []))
    alerter.alert(
        "Engine Stopped", f"Strategy: {run_id}\nMode: Paper\nTrades: {trades}\nTotal P&L: \u20b9{pnl:.2f}", level="warn"
    )

    return {"status": "stopped", "run_id": run_id}


@app.post("/api/paper/exit-position")
async def paper_exit_position(request: Request):
    """Force-exit an open position in a running paper engine."""
    user_id = _request_user_id(request)
    paper_bucket = _registry_bucket(paper_engines, user_id)
    body = await request.json()
    run_id = body.get("run_id", "")
    pos_index = body.get("position_index", 0)

    engine = paper_bucket.get(run_id)
    if not engine:
        # Try first running engine
        for rid, eng in paper_bucket.items():
            if eng.running:
                engine = eng
                run_id = rid
                break
    if not engine or not engine.running:
        return {"status": "error", "message": "No running paper engine found"}

    if pos_index >= len(engine.positions):
        return {"status": "error", "message": f"Position index {pos_index} out of range"}

    pos = engine.positions[pos_index]
    current_premium = pos.get("current_premium", pos.get("entry_premium", 0))
    engine._close_position(pos, "MANUAL_EXIT", current_premium)
    return {"status": "ok", "message": f"Position {pos.get('trading_symbol', pos.get('symbol', ''))} exited manually"}


@app.post("/api/live/exit-position")
async def live_exit_position(request: Request):
    """Force-exit an open position in a running live engine."""
    user_id = _request_user_id(request)
    live_bucket = _registry_bucket(live_engines, user_id)
    body = await request.json()
    run_id = body.get("run_id", "")
    pos_index = body.get("position_index", 0)

    engine = live_bucket.get(run_id)
    if not engine:
        for rid, eng in live_bucket.items():
            if eng.running:
                engine = eng
                run_id = rid
                break
    if not engine or not engine.running:
        return {"status": "error", "message": "No running live engine found"}

    if pos_index >= len(engine.positions):
        return {"status": "error", "message": f"Position index {pos_index} out of range"}

    pos = engine.positions[pos_index]
    current_premium = pos.get("current_premium", pos.get("entry_premium", 0))

    async def broadcast(event: dict):
        await _broadcast_user_ws_json(user_id, {"source": "live", "run_id": run_id, **event})
        await _check_trade_alerts(run_id, "Auto", event, user_id=user_id)
        if event.get("type") == "exit" and event.get("trade"):
            await _save_single_trade_to_history(event["trade"], "live", run_name=run_id, explicit_user_id=user_id)

    result = await engine._exit_position(pos, "MANUAL_EXIT", current_premium, callback=broadcast)
    status = str((result or {}).get("status") or "error").lower()
    symbol = pos.get("trading_symbol", pos.get("symbol", "position"))

    if status == "ok":
        return {
            "status": "ok",
            "message": result.get("message") or f"Position {symbol} exited",
            "engine_status": engine.get_status(),
            "trade": result.get("trade"),
        }
    if status == "partial":
        return {
            "status": "partial",
            "message": result.get("message") or f"Position {symbol} partially exited",
            "remaining_qty": result.get("remaining_qty", 0),
            "engine_status": engine.get_status(),
            "trade": result.get("trade"),
        }
    if status == "pending":
        return {
            "status": "pending",
            "message": result.get("message") or f"Position {symbol} exit retry pending",
            "engine_status": engine.get_status(),
        }
    return {
        "status": "error",
        "message": result.get("message") or f"Position {symbol} exit failed",
        "engine_status": engine.get_status(),
    }


def _history_trade_signature(trade: dict) -> dict | None:
    if not isinstance(trade, dict):
        return None
    return {
        "symbol": trade.get("symbol") or trade.get("trading_symbol") or "",
        "transaction_type": trade.get("transaction_type") or trade.get("side") or "",
        "option_type": trade.get("option_type") or "",
        "strike": trade.get("strike"),
        "entry_time": str(trade.get("entry_time") or ""),
        "exit_time": str(trade.get("exit_time") or ""),
        "entry_premium": round(float(trade.get("entry_premium") or trade.get("entry_price") or 0), 4),
        "exit_premium": round(float(trade.get("exit_premium") or trade.get("exit_price") or 0), 4),
        "quantity": trade.get("quantity") or trade.get("lots") or "",
        "pnl": round(float(trade.get("pnl") or 0), 4),
        "reason": trade.get("exit_reason") or trade.get("reason") or "",
    }


def _history_trade_counter(trades: list[dict]) -> Counter[str]:
    counter: Counter[str] = Counter()
    for trade in trades or []:
        sig = _history_trade_signature(trade)
        if sig:
            counter[json.dumps(sig, sort_keys=True, default=str)] += 1
    return counter


def _history_persistence_trade_signature(trade: dict) -> dict | None:
    """Stable trade identity for persistence, excluding reconciliation fields.

    An exit is saved immediately so a restart cannot lose it.  When the run is
    subsequently stopped, the complete closed-trade list is saved too.  P&L and
    exit text may have changed after broker reconciliation, but that is still
    the same execution and must not create a second historical record.
    """
    if not isinstance(trade, dict):
        return None
    return {
        "symbol": trade.get("symbol") or trade.get("trading_symbol") or "",
        "transaction_type": trade.get("transaction_type") or trade.get("side") or "",
        "option_type": trade.get("option_type") or "",
        "strike": trade.get("strike"),
        "entry_time": str(trade.get("entry_time") or ""),
        "exit_time": str(trade.get("exit_time") or ""),
        "entry_premium": round(float(trade.get("entry_premium") or trade.get("entry_price") or 0), 4),
        "exit_premium": round(float(trade.get("exit_premium") or trade.get("exit_price") or 0), 4),
        "quantity": trade.get("quantity") or trade.get("lots") or "",
    }


def _history_persistence_trade_counter(trades: list[dict]) -> Counter[str]:
    counter: Counter[str] = Counter()
    for trade in trades or []:
        sig = _history_persistence_trade_signature(trade)
        if sig:
            counter[json.dumps(sig, sort_keys=True, default=str)] += 1
    return counter


def _history_run_signature(run: dict) -> tuple:
    mode = str(run.get("mode") or "")
    run_name = str(run.get("run_name") or run.get("strategy_name") or "")
    trades = run.get("trades") or []
    total_pnl = round(float(run.get("total_pnl") or 0), 2)
    normalized = [sig for trade in trades if (sig := _history_trade_signature(trade))]
    normalized.sort(
        key=lambda item: (
            item["entry_time"],
            item["exit_time"],
            item["symbol"],
            item["transaction_type"],
        )
    )
    return (
        mode,
        run_name,
        int(run.get("trade_count") or len(normalized)),
        total_pnl,
        json.dumps(normalized, sort_keys=True, default=str),
    )


async def _save_single_trade_to_history(
    trade: dict, mode: str, run_name: str = "", explicit_user_id: int | None = None
) -> None:
    """Save a single closed trade (paper/live) to user-scoped run history in real time."""
    try:
        user_id = await _resolve_history_user_id(explicit_user_id, trade)
        pnl = round(trade.get("pnl", 0), 2)
        instrument = trade.get("instrument", trade.get("symbol", ""))
        side = trade.get("side", trade.get("trade_side", ""))
        label = mode.title()
        name = run_name or f"{label} {instrument} {side}"
        run_entry = {
            "mode": mode,
            "run_name": name,
            "instrument": instrument,
            "status": "completed",
            "started_at": str(trade.get("entry_time", "")),
            "stopped_at": str(trade.get("exit_time", "")),
            "trade_count": 1,
            "total_pnl": pnl,
            "stats": {
                "total_trades": 1,
                "winning_trades": 1 if pnl > 0 else 0,
                "losing_trades": 1 if pnl <= 0 else 0,
                "win_rate": 100.0 if pnl > 0 else 0.0,
                "total_pnl": pnl,
            },
            "trades": [trade],
            "created_at": str(datetime.now()),
        }
        target_sig = _history_run_signature(run_entry)
        runs = await _db_mod.list_runs(user_id)
        if any(_history_run_signature(r) == target_sig for r in runs):
            print(f"[{mode.upper()}] Identical single-trade history already exists — skipping duplicate save")
            return
        saved = await _db_mod.create_run_record(user_id, run_entry)
        _logger.info("[%s] Saved one trade to run history record_id=%s", mode.upper(), saved["id"])
    except Exception as e:
        print(f"[{mode.upper()}] Failed to save trade to history: {e}")


async def _save_paper_run_to_history(status: dict, explicit_user_id: int | None = None):
    """Save a completed paper trading run to user-scoped history."""
    try:
        closed = status.get("closed_trades", [])
        if not closed:
            print("[PAPER] No closed trades — skipping history save")
            return

        user_id = await _resolve_history_user_id(explicit_user_id, status)
        run_name = status.get("strategy_name", "Paper Run")
        runs = await _db_mod.list_runs(user_id)
        existing = Counter()
        for run in runs:
            trade_count = int(run.get("trade_count") or len(run.get("trades") or []))
            if run.get("mode") != "paper" or run.get("run_name") != run_name or trade_count != 1:
                continue
            existing += _history_persistence_trade_counter(run.get("trades") or [])
        closed_sigs = _history_persistence_trade_counter(closed)
        if closed_sigs and all(existing[key] >= count for key, count in closed_sigs.items()):
            print(f"[PAPER] All {len(closed)} trades already saved individually — skipping bulk save")
            return

        total_pnl = round(sum(t.get("pnl", 0) for t in closed), 2)
        winners = [t for t in closed if t.get("pnl", 0) > 0]
        losers = [t for t in closed if t.get("pnl", 0) <= 0]
        win_rate = round(len(winners) / len(closed) * 100, 2) if closed else 0

        paper_run = {
            "mode": "paper",
            "run_name": status.get("strategy_name", "Paper Run"),
            "instrument": status.get("instrument", ""),
            "status": "completed",
            "started_at": str(datetime.now()),
            "stopped_at": str(datetime.now()),
            "trade_count": len(closed),
            "total_pnl": total_pnl,
            "stats": {
                "total_trades": len(closed),
                "winning_trades": len(winners),
                "losing_trades": len(losers),
                "win_rate": win_rate,
                "total_pnl": total_pnl,
                "avg_profit": round(sum(t["pnl"] for t in winners) / len(winners), 2) if winners else 0,
                "avg_loss": round(sum(t["pnl"] for t in losers) / len(losers), 2) if losers else 0,
            },
            "trades": closed,
            "created_at": str(datetime.now()),
            **{
                k: v
                for k, v in (status.get("strategy") or {}).items()
                if k
                in (
                    "indicators",
                    "entry_conditions",
                    "exit_conditions",
                    "legs",
                    "lots",
                    "lot_size",
                    "stoploss_pct",
                    "stoploss_rupees",
                    "sl_type",
                    "target_profit_pct",
                    "target_profit_rupees",
                    "tp_type",
                    "market_open",
                    "market_close",
                    "folder",
                    "max_trades_per_day",
                    "skip_days_after_profit",
                    "skip_profit_threshold_rupees",
                    "signal_cutoff_time",
                )
            },
        }

        target_sig = _history_run_signature(paper_run)
        if any(_history_run_signature(r) == target_sig for r in runs):
            print("[PAPER] Identical completed run already exists — skipping duplicate history save")
            return

        saved = await _db_mod.create_run_record(user_id, paper_run)
        _logger.info("[PAPER] Saved completed run record_id=%s trade_count=%s", saved["id"], len(closed))
    except Exception as e:
        print(f"[PAPER] Failed to save run to history: {e}")


async def _save_scalp_run_to_history(eng, explicit_user_id: int | None = None) -> None:
    """Persist a completed scalp session to user-scoped run history."""
    try:
        status = eng.get_status()
        closed = status.get("closed_trades", [])
        if not closed:
            print("[SCALP] No closed trades — skipping history save")
            return

        user_id = await _resolve_history_user_id(explicit_user_id, status)
        total_pnl = round(sum(t.get("pnl", 0) for t in closed), 2)
        winners = [t for t in closed if t.get("pnl", 0) > 0]
        losers = [t for t in closed if t.get("pnl", 0) <= 0]
        win_rate = round(len(winners) / len(closed) * 100, 2) if closed else 0

        underlyings = list(dict.fromkeys(t.get("underlying", "") for t in closed if t.get("underlying")))
        run_name = "Scalp — " + ", ".join(underlyings) if underlyings else "Scalp Session"

        scalp_run = {
            "mode": "scalp",
            "run_name": run_name,
            "instrument": underlyings[0] if underlyings else "",
            "status": "completed",
            "started_at": closed[-1].get("entry_time", str(datetime.now())),
            "stopped_at": str(datetime.now()),
            "trade_count": len(closed),
            "total_pnl": total_pnl,
            "stats": {
                "total_trades": len(closed),
                "winning_trades": len(winners),
                "losing_trades": len(losers),
                "win_rate": win_rate,
                "total_pnl": total_pnl,
                "avg_profit": round(sum(t["pnl"] for t in winners) / len(winners), 2) if winners else 0,
                "avg_loss": round(sum(t["pnl"] for t in losers) / len(losers), 2) if losers else 0,
            },
            "trades": closed,
            "created_at": str(datetime.now()),
        }

        saved = await _db_mod.create_run_record(user_id, scalp_run)
        _logger.info("[SCALP] Saved completed run record_id=%s trade_count=%s", saved["id"], len(closed))
    except Exception as e:
        print(f"[SCALP] Failed to save run to history: {e}")


async def _save_live_run_to_history(status: dict, explicit_user_id: int | None = None):
    """Save a completed live (auto) trading run to user-scoped history."""
    try:
        closed = status.get("closed_trades", [])
        if not closed:
            print("[LIVE] No closed trades — skipping history save")
            return

        user_id = await _resolve_history_user_id(explicit_user_id, status)
        run_name = status.get("strategy_name", "Live Run")
        runs = await _db_mod.list_runs(user_id)
        existing = Counter()
        for run in runs:
            trade_count = int(run.get("trade_count") or len(run.get("trades") or []))
            if run.get("mode") != "live" or run.get("run_name") != run_name or trade_count != 1:
                continue
            existing += _history_persistence_trade_counter(run.get("trades") or [])
        closed_sigs = _history_persistence_trade_counter(closed)
        if closed_sigs and all(existing[key] >= count for key, count in closed_sigs.items()):
            print(f"[LIVE] All {len(closed)} trades already saved individually — skipping bulk save")
            return

        total_pnl = round(sum(t.get("pnl", 0) for t in closed), 2)
        winners = [t for t in closed if t.get("pnl", 0) > 0]
        losers = [t for t in closed if t.get("pnl", 0) <= 0]
        win_rate = round(len(winners) / len(closed) * 100, 2) if closed else 0

        live_run = {
            "mode": "live",
            "run_name": status.get("strategy_name", "Live Run"),
            "instrument": status.get("instrument", ""),
            "status": "completed",
            "started_at": str(datetime.now()),
            "stopped_at": str(datetime.now()),
            "trade_count": len(closed),
            "total_pnl": total_pnl,
            "stats": {
                "total_trades": len(closed),
                "winning_trades": len(winners),
                "losing_trades": len(losers),
                "win_rate": win_rate,
                "total_pnl": total_pnl,
                "avg_profit": round(sum(t["pnl"] for t in winners) / len(winners), 2) if winners else 0,
                "avg_loss": round(sum(t["pnl"] for t in losers) / len(losers), 2) if losers else 0,
            },
            "trades": closed,
            "created_at": str(datetime.now()),
            **{
                k: v
                for k, v in (status.get("strategy") or {}).items()
                if k
                in (
                    "indicators",
                    "entry_conditions",
                    "exit_conditions",
                    "legs",
                    "lots",
                    "lot_size",
                    "stoploss_pct",
                    "stoploss_rupees",
                    "sl_type",
                    "target_profit_pct",
                    "target_profit_rupees",
                    "tp_type",
                    "market_open",
                    "market_close",
                    "folder",
                    "max_trades_per_day",
                    "skip_days_after_profit",
                    "skip_profit_threshold_rupees",
                    "signal_cutoff_time",
                )
            },
        }

        target_sig = _history_run_signature(live_run)
        if any(_history_run_signature(r) == target_sig for r in runs):
            print("[LIVE] Identical completed run already exists — skipping duplicate history save")
            return

        saved = await _db_mod.create_run_record(user_id, live_run)
        _logger.info("[LIVE] Saved completed run record_id=%s trade_count=%s", saved["id"], len(closed))
    except Exception as e:
        print(f"[LIVE] Failed to save run to history: {e}")


@app.get("/api/paper/status")
async def paper_status(request: Request, run_id: str = ""):
    """Get paper trading status. If run_id empty, returns first running engine."""
    user_id = _request_user_id(request)
    paper_bucket = _registry_bucket(paper_engines, user_id)
    if run_id and run_id in paper_bucket:
        return paper_bucket[run_id].get_status()

    # Return first running engine's status
    for rid, engine in paper_bucket.items():
        if engine.running:
            return engine.get_status()

    # No running engines — check for last saved paper run from history
    status = {
        "running": False,
        "run_id": "",
        "mode": "paper",
        "in_trade": False,
        "positions": [],
        "closed_trades": [],
        "total_pnl": 0,
        "trades_today": 0,
        "strategy_name": "",
        "instrument": "",
        "current_candle": {},
        "current_indicators": {},
        "event_log": [],
    }
    try:
        runs = await _db_mod.list_runs(_request_user_id(request))
        paper_runs = [r for r in runs if r.get("mode") == "paper"]
        if paper_runs:
            last = paper_runs[-1]
            trades = last.get("trades", [])
            status["strategy_name"] = last.get("run_name", "Last Paper Run")
            status["instrument"] = last.get("instrument", "")
            status["closed_trades"] = trades
            status["trades_today"] = len(trades)
            status["total_pnl"] = last.get("total_pnl", 0)
            status["_from_history"] = True
    except Exception:
        pass

    return status


# ── Combined Engines Status (Multi-Strategy Monitor) ─────────────
@app.get("/api/engines/all")
async def engines_all(request: Request):
    """Return status of the current user's running engines for the Live page."""
    user_id = _request_user_id(request)
    engines = []
    stopped_engines = _load_stopped_engines(user_id)
    strategy_rows = await _db_mod.list_strategies(user_id)
    strategy_folder_map: dict[str, str] = {}
    strategy_by_id: dict[int, dict] = {}
    strategy_name_matches: dict[str, list[dict]] = defaultdict(list)
    for strategy in strategy_rows:
        strategy_name = str(strategy.get("run_name") or strategy.get("name") or "").strip().casefold()
        strategy_id = int(strategy.get("id") or 0)
        if strategy_id:
            strategy_by_id[strategy_id] = strategy
        if strategy_name and not strategy.get("_placeholder"):
            strategy_name_matches[strategy_name].append(strategy)
            strategy_folder_map[strategy_name] = str(strategy.get("folder") or "").strip() or "Intraday"

    def _attach_strategy_folder(status: dict) -> dict:
        if not isinstance(status, dict):
            return status
        strategy_payload = status.get("strategy") if isinstance(status.get("strategy"), dict) else None
        strategy_id = int(status.get("strategy_id") or (strategy_payload or {}).get("strategy_id") or 0)
        explicit_folder = str(status.get("folder") or (strategy_payload or {}).get("folder") or "").strip()
        strategy_name = str(
            status.get("strategy_name")
            or (strategy_payload or {}).get("run_name")
            or (strategy_payload or {}).get("name")
            or ""
        ).strip()
        matched_strategy = strategy_by_id.get(strategy_id) if strategy_id else None
        if not matched_strategy and strategy_name:
            matches = list(strategy_name_matches.get(strategy_name.casefold(), []))
            if explicit_folder:
                folder_key = (explicit_folder or "Intraday").strip().casefold()
                folder_matches = [
                    s for s in matches if (str(s.get("folder") or "").strip() or "Intraday").casefold() == folder_key
                ]
                if len(folder_matches) == 1:
                    matched_strategy = folder_matches[0]
            if not matched_strategy and len(matches) == 1:
                matched_strategy = matches[0]
        resolved_folder = explicit_folder
        if matched_strategy:
            resolved_folder = str(matched_strategy.get("folder") or "").strip() or "Intraday"
            status["strategy_id"] = int(matched_strategy.get("id") or strategy_id or 0)
            if strategy_payload is not None:
                strategy_payload.setdefault("strategy_id", status["strategy_id"])
        elif not resolved_folder and strategy_name:
            resolved_folder = strategy_folder_map.get(strategy_name.casefold(), "")
        if resolved_folder:
            status["folder"] = resolved_folder
            if strategy_payload is not None and not strategy_payload.get("folder"):
                strategy_payload["folder"] = resolved_folder
        return status

    # Add all paper engines
    for run_id, engine in _registry_bucket(paper_engines, user_id).items():
        if engine.running:
            st = _attach_strategy_folder(engine.get_status())
            st["run_id"] = run_id
            st["mode"] = "paper"
            engines.append(st)

    # Add all live engines
    #
    # A LIVE BOOK SHOWS WHAT IT TRADED, NOT WHAT IT TRADED SINCE IT RESTARTED.
    # `get_status()` reports the engine's own closed list, which begins empty at
    # every restart -- so CE_SL15_NoMonTue read "0 trades" and Rs 0.00 on this
    # page while its real CE of 2026-09-03 sat in the broker's record. The
    # account fills the gap here, and ONLY here: the CE + PE desk
    # (/api/live/runs) already prints that record in a table of its own, and
    # doing it in both places showed every trade twice.
    account_rows = await _account_option_history(user_id) if _registry_bucket(live_engines, user_id) else []
    for run_id, engine in _registry_bucket(live_engines, user_id).items():
        if engine.running:
            st = _attach_strategy_folder(engine.get_status())
            st["run_id"] = run_id
            st["mode"] = "auto"
            engines.append(_with_account_history(st, account_rows))

    # Add stopped engine snapshots (persisted panels)
    active_ids = {_engine_status_key(e) for e in engines}
    for snapshot in stopped_engines.values():
        snapshot_key = _engine_status_key(snapshot)
        if snapshot_key not in active_ids:
            engines.append(_attach_strategy_folder(snapshot))
            active_ids.add(snapshot_key)

    # Fallback for migrated/admin sessions: if today's persisted engine state
    # exists but restore/stopped snapshots are absent, synthesize idle panels so
    # the Live page does not appear blank.
    if not engines:
        for snapshot in _state_file_snapshots(user_id):
            snapshot_key = _engine_status_key(snapshot)
            if snapshot.get("run_id") and snapshot_key not in active_ids:
                engines.append(_attach_strategy_folder(snapshot))
                active_ids.add(snapshot_key)

    return {"engines": engines, "count": len(engines)}


@app.post("/api/engines/dismiss")
async def engines_dismiss(request: Request):
    """Remove a stopped engine snapshot from the Live page."""
    user_id = _request_user_id(request)
    stopped_engines = _load_stopped_engines(user_id)
    body = {}
    try:
        body = await request.json()
    except Exception:
        pass
    run_id = body.get("run_id", "")
    mode = body.get("mode", "")
    if run_id and mode:
        snapshot_key = _engine_snapshot_key(run_id, mode)
        if snapshot_key not in stopped_engines:
            return {"status": "not_found", "run_id": run_id, "mode": _normalize_engine_mode(mode)}
        stopped_engines.pop(snapshot_key, None)
        _save_stopped_engines(user_id)
        return {"status": "dismissed", "run_id": run_id, "mode": _normalize_engine_mode(mode)}
    if run_id:
        removed = [key for key, snapshot in stopped_engines.items() if str(snapshot.get("run_id") or "") == str(run_id)]
        for key in removed:
            stopped_engines.pop(key, None)
        if not removed:
            return {"status": "not_found", "run_id": run_id}
        _save_stopped_engines(user_id)
        return {"status": "dismissed", "run_id": run_id}
    return {"status": "not_found", "run_id": run_id}


# ── WebSocket ─────────────────────────────────────────────────────


# Event-driven signal: set whenever scalp state changes (entry/exit/modify)
_scalp_ws_event: asyncio.Event | None = None


def _get_scalp_ws_event() -> asyncio.Event:
    global _scalp_ws_event
    if _scalp_ws_event is None:
        _scalp_ws_event = asyncio.Event()
    return _scalp_ws_event


def _notify_scalp_ws():
    """Signal all WS clients to push scalp update immediately."""
    evt = _get_scalp_ws_event()
    evt.set()


def _ws_serialize(payload: dict) -> bytes:
    """Serialize WS payload using orjson (fast) with stdlib json fallback."""
    if _orjson is not None:
        return _orjson.dumps(payload)
    return json.dumps(payload).encode("utf-8")


@app.websocket("/ws")
async def websocket_endpoint(ws: WebSocket):
    raw_origin = ws.headers.get("origin")
    origin = _normalize_origin_value(raw_origin or "")
    websocket_origins = {_normalize_origin_value(value) for value in _CORS_ALLOWED_ORIGINS}
    if raw_origin is not None and (not origin or origin not in websocket_origins):
        await ws.close(code=4003, reason="Forbidden origin")
        return
    # Authenticate WebSocket via session cookie (DB-backed)
    token = ws.cookies.get(_SESSION_COOKIE_NAME, "")
    session = await _validate_session_async(token)
    if not session:
        await ws.close(code=4001, reason="Unauthorized")
        return
    user_id = int(session["user_id"])
    user = await _db_mod.get_user_by_id(user_id)
    if not user or not user.get("is_active"):
        await ws.close(code=4001, reason="Account disabled or not found")
        return
    await ws.accept()
    _user_ws_clients(user_id).append(ws)

    scalp_evt = _get_scalp_ws_event()
    engine_tick = 0  # counter: send full engine status every 20 cycles (~5s)
    authorization_tick = 0

    try:
        while True:
            # Wait for either: scalp event fires OR 250ms timeout
            try:
                await asyncio.wait_for(scalp_evt.wait(), timeout=0.25)
                scalp_evt.clear()
            except asyncio.TimeoutError:
                pass

            # Scalp status — every cycle (250ms)
            scalp_data = None
            scalp_engine = _scalp_engines.get(int(user_id))
            if _HAS_SCALP and scalp_engine is not None:
                try:
                    scalp_data = scalp_engine.get_status()
                except Exception:
                    pass

            payload = {"type": "status", "_ts": time.time()}

            if scalp_data is not None:
                payload["scalp"] = scalp_data

            # Engine status — every ~5s (20 × 250ms) to avoid waste
            engine_tick += 1
            authorization_tick += 1
            if authorization_tick >= 240:
                authorization_tick = 0
                current_session = await _validate_session_async(token)
                current_user = await _db_mod.get_user_by_id(user_id) if current_session else None
                if not current_user or not current_user.get("is_active"):
                    await ws.close(code=4001, reason="Session expired or account disabled")
                    break
            if engine_tick >= 20:
                engine_tick = 0
                paper_sts = {
                    rid: e.get_status() for rid, e in _registry_bucket(paper_engines, user_id).items() if e.running
                }
                live_sts = {
                    rid: e.get_status() for rid, e in _registry_bucket(live_engines, user_id).items() if e.running
                }
                payload["paper_engines"] = paper_sts
                payload["live_engines"] = live_sts
                payload["paper_running"] = any(s.get("running") for s in paper_sts.values())
                payload["live_running"] = any(s.get("running") for s in live_sts.values())
                cascade_runtime = _cascade_engines.get(int(user_id))
                if cascade_runtime is not None:
                    payload["cascade"] = {**cascade_runtime.engine.get_status(), "running": cascade_runtime.running}

            await ws.send_bytes(_ws_serialize(payload))
    except (WebSocketDisconnect, Exception):
        pass
    finally:
        if ws in _user_ws_clients(user_id):
            _user_ws_clients(user_id).remove(ws)


