async def _backfill_in_background():
    """Run the blocking backfill in a thread so the event loop stays free."""
    global _backfill_state
    _backfill_state["status"] = "running"
    _backfill_state["message"] = "Fetching historical trades from Dhan..."
    loop = asyncio.get_event_loop()
    try:
        admin = await _get_preferred_admin_user()
        if not admin:
            raise RuntimeError("No admin user available for startup trade-history backfill")
        admin_id = int(admin["id"])
        broker_client, source = _resolve_user_broker_client(admin, allow_admin_fallback=True)
        if not broker_client:
            raise RuntimeError(_broker_not_configured_message(admin, source))
        history = await _db_mod.list_trade_history(admin_id)
        force = len(history) <= 2
        refresh_from_date = "2024-01-01" if force else _trade_history_refresh_start(history, "2024-01-01")
        if force:
            _backfill_state["message"] = "First-run: full backfill in progress..."
            print("📊 [BACKFILL] Auto-backfilling trade history from Dhan (force)...")
        elif refresh_from_date != "2024-01-01":
            _backfill_state["message"] = f"Refreshing trade history from {refresh_from_date}..."
        count = await loop.run_in_executor(
            None,
            lambda: _backfill_trade_history(
                refresh_from_date,
                force=force,
                user_id=admin_id,
                broker_client=broker_client,
            ),
        )
        if force:
            print(f"📊 [BACKFILL] Done — loaded {count} days of historical trades")
        else:
            loaded = await _db_mod.list_trade_history(admin_id)
            print(f"📊 [TRADE_HISTORY] {len(loaded)} days of trade data ({count} refreshed)")
        # TODAY IS NOT PART OF THE BACKFILL, so nothing was rewriting it. Its
        # row is written once from whatever fills existed at the time and then
        # only refreshed if somebody happened to open the trades page. On
        # 2026-09-10 that left the day showing Rs 0 -- a buy, no sell -- for
        # hours after the position had been closed and settled. Ask once, here.
        try:
            todays_fills = await asyncio.to_thread(broker_client.get_trades)
            if isinstance(todays_fills, list) and todays_fills:
                await _persist_daily_trades(todays_fills, admin_id)
        except Exception as exc:
            print(f"📊 [TRADE_HISTORY] Could not refresh today from the broker: {exc}")

        _backfill_state.update({"status": "done", "message": "Trade history up to date.", "new_dates": count})
    except Exception as e:
        print(f"📊 [BACKFILL] Startup backfill failed: {e}")
        _backfill_state.update({"status": "error", "message": str(e)})


async def _journal_chart_backfill_once() -> dict:
    """Build missing admin Journal charts in a worker thread.

    This is intentionally a display/archive job.  Its module reads Upstox
    historical candles and Pillow-renders PNGs; it never receives a Dhan client
    and cannot place, modify, or cancel an order.
    """
    from journal_charts import backfill_charts

    admin = await _get_preferred_admin_user()
    if not admin:
        raise RuntimeError("No admin user available for daily Journal charts")
    user_id = int(admin["id"])
    charts_root = _user_charts_root(user_id)
    cache_root = os.path.join(_user_storage_root(user_id), "journal_chart_data")
    start_text = os.getenv("PHILFORGE_JOURNAL_CHART_START", "2023-01-01").strip()
    try:
        backfill_start = date.fromisoformat(start_text)
    except ValueError as exc:
        raise RuntimeError("PHILFORGE_JOURNAL_CHART_START must be YYYY-MM-DD") from exc
    _journal_chart_state.update(
        {
            "status": "running",
            "message": "Checking NIFTY and SENSEX Journal charts...",
            "last_run": datetime.now(IST).isoformat(),
        }
    )
    result = await asyncio.to_thread(backfill_charts, charts_root, cache_root, start=backfill_start)
    created = len(result.get("created") or [])
    consolidated = len(result.get("consolidated") or [])
    errors = len(result.get("errors") or [])
    message = f"Daily Journal charts are current; {created} image{'s' if created != 1 else ''} added."
    if consolidated:
        message += (
            f" {consolidated} generated image{'s' if consolidated != 1 else ''} merged into existing date folders."
        )
    if result.get("status") == "pending":
        pending_symbols = ", ".join(str(item.get("symbol")) for item in result.get("pending") or [])
        message = (
            f"Waiting for complete {result.get('through')} market data"
            f" ({pending_symbols or 'NIFTY, SENSEX'}); the Journal job will retry automatically."
        )
    if errors:
        message = f"Daily Journal chart run completed with {errors} data/render error{'s' if errors != 1 else ''}."
    _journal_chart_state.update(
        {
            "status": result.get("status", "error"),
            "message": message,
            "last_run": datetime.now(IST).isoformat(),
            "result": result,
        }
    )
    return result


async def _run_journal_chart_loop() -> None:
    """Catch up on startup, then create the new pair once each market day."""
    global _journal_chart_wakeup
    if _journal_chart_wakeup is None:
        _journal_chart_wakeup = asyncio.Event()
    last_success_through = ""
    interval = max(300, int(os.getenv("PHILFORGE_JOURNAL_CHART_CHECK_SECONDS", "900")))
    while True:
        try:
            # Both blue/green workers may exist, but only the active instance
            # may write. The standby keeps looping and naturally takes over
            # after the active-port marker flips during deployment.
            if _engine_restore_owner_is_active_instance():
                from journal_charts import eligible_through

                through = eligible_through(datetime.now(IST)).isoformat()
                if through != last_success_through:
                    try:
                        result = await _journal_chart_backfill_once()
                    except Exception as exc:
                        _logger.warning("[JOURNAL CHARTS] Daily job failed: %s", exc)
                        _journal_chart_state.update(
                            {
                                "status": "error",
                                "message": str(exc),
                                "last_run": datetime.now(IST).isoformat(),
                            }
                        )
                    else:
                        if result.get("status") == "ok":
                            last_success_through = through
                            _logger.info(
                                "[JOURNAL CHARTS] Through %s: %d created, %d skipped",
                                through,
                                len(result.get("created") or []),
                                len(result.get("skipped") or []),
                            )
            try:
                await asyncio.wait_for(_journal_chart_wakeup.wait(), timeout=interval)
                _journal_chart_wakeup.clear()
            except TimeoutError:
                pass
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            _logger.warning("[JOURNAL CHARTS] Scheduler recovered from: %s", exc)
            await asyncio.sleep(interval)


def _wake_journal_chart_loop() -> bool:
    """Wake the Journal job as soon as a standby becomes the active worker."""
    global _journal_chart_task, _journal_chart_wakeup
    if not _STARTUP_JOURNAL_CHARTS_ENABLED:
        return False
    if _journal_chart_wakeup is None:
        _journal_chart_wakeup = asyncio.Event()
    if _journal_chart_task is None or _journal_chart_task.done():
        _journal_chart_task = asyncio.create_task(_run_journal_chart_loop())
    _journal_chart_wakeup.set()
    return True


